// =====================================================================
// W57 d01：为什么要多阶段：镜像体积从哪来。
//
// 最终镜像不是"跑起来的那份小"，而是"出现过的那叠层全都算"。单阶段 Dockerfile 会把
// Go SDK、模块缓存、构建残渣一起推到生产机上——绝大多数运行时根本用不到。多阶段把
// 「构建」与「运行」切成两段：builder 整段丢弃，只 COPY --from 出那一个二进制，落进
// scratch / alpine / distroless 三种新底。今天产四版 Dockerfile 文本，按固定的「层
// 清单」把各版体积逐层加起来、用程序做差打对照表。
//
// 本机校验边界（无 Docker 守护进程，全程不调 docker/nginx/psql）：体积数字全按清单现算并两条独立路径对账；CGO_ENABLED=0 静态链接是本机唯一真验项，只打布尔与阈值。
//
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d01
// =====================================================================
package main

import (
	"fmt"
	"os"
	"os/exec"
	"sort"
	"strings"
)

var yes = map[bool]string{true: "是", false: "否"}

func hdr(n int, s string) { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func pad(s string, wd int) string {
	n := 0
	for _, r := range s {
		if r > 0x2E80 {
			n += 2
		} else {
			n++
		}
	}
	return s + strings.Repeat(" ", wd-n)
}

const binMiB = 18 // 清单口径的"应用二进制"层，第 4 节拿它当固定阈值
type manifest struct {
	tag, note, base, extra, dst string
	layers                      map[string]int
}

func (m manifest) total() int {
	s := 0
	for _, v := range m.layers {
		s += v
	}
	return s
}
func (m manifest) has(k string) bool { return m.layers[k] > 0 }
func (m manifest) text() string {
	head := "# homecube/deploy/docker/Dockerfile.finance." + m.tag + "\n"
	if m.tag == "single" {
		return head + singleFinal
	}
	lines := []string{m.base}
	if m.extra != "" {
		lines = append(lines, m.extra)
	}
	lines = append(lines, "COPY --from=builder /out/svc-finance "+m.dst, "EXPOSE 8083", fmt.Sprintf(`ENTRYPOINT ["%s"]`, m.dst))
	return head + builderPrelude + "\n\n" + strings.Join(lines, "\n")
}

const builderPrelude = `FROM golang:1.22.5-bookworm AS builder
WORKDIR /src
COPY go.mod go.sum ./
RUN go mod download
COPY . .
RUN CGO_ENABLED=0 go build -trimpath -ldflags "-s -w -buildid=" -o /out/svc-finance ./cmd/svc-finance`
const singleFinal = `FROM golang:1.22.5-bookworm
WORKDIR /src
COPY . .
RUN CGO_ENABLED=0 go build -o /out/svc-finance ./cmd/svc-finance
EXPOSE 8083
CMD ["/out/svc-finance"]`

var manifests = []manifest{
	{"single", "单阶段：构建与运行共用一个底，SDK/模块缓存/残渣全跟着上线", "", "", "", map[string]int{"go SDK 底层(golang:1.22.5-bookworm)": 1024, "go 模块缓存层": 256, "源码 COPY 层": 12, "构建缓存残渣层": 40, "应用二进制层": binMiB}},
	{"scratch", "builder→scratch：只剩二进制，证书/时区也没有", "FROM scratch", "", "/svc-finance", map[string]int{"应用二进制层": binMiB}},
	{"alpine", "builder→alpine：补上 CA 与 tzdata 的最小 Linux", "FROM alpine:3.20.3", "RUN apk add --no-cache ca-certificates tzdata", "/usr/local/bin/svc-finance", map[string]int{"alpine 底层": 8, "CA 证书层": 6, "tzdata 时区层": 3, "应用二进制层": binMiB}},
	{"distroless", "builder→distroless：没有 shell，攻击面最小", "FROM gcr.io/distroless/static-debian12:nonroot", "", "/svc-finance", map[string]int{"distroless 底层": 19, "CA 证书层": 6, "tzdata 时区层": 2, "应用二进制层": binMiB}},
}

func hasEnvWith(t string, subs ...string) bool {
	for _, ln := range strings.Split(t, "\n") {
		ln = strings.TrimSpace(ln)
		for _, s := range subs {
			if strings.HasPrefix(ln, "ENV ") && strings.Contains(ln, s) {
				return true
			}
		}
	}
	return false
}
func probeStatic(goos string) (built, static bool, size int64) {
	dir, _ := os.MkdirTemp("", "hc-w57-d01")
	defer os.RemoveAll(dir)
	os.WriteFile(dir+"/go.mod", []byte("module hcprobe\n\ngo 1.22\n"), 0o644)
	os.WriteFile(dir+"/main.go", []byte("package main\n\nfunc main() {}\n"), 0o644)
	cmd := exec.Command("go", "build", "-o", dir+"/probe.bin", ".")
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GOOS="+goos, "GOARCH=amd64", "CGO_ENABLED=0")
	if err := cmd.Run(); err != nil {
		return false, false, 0
	}
	if fi, err := os.Stat(dir + "/probe.bin"); err == nil {
		size = fi.Size()
	}
	out, err := exec.Command("file", dir+"/probe.bin").Output()
	return true, err == nil && strings.Contains(string(out), "statically linked"), size
}
func main() {
	single := manifests[0]
	hdr(1, "层清单：体积的原始材料（每层大小记在清单里，求和/做差全由程序算）")
	names := map[string]int{}
	for _, m := range manifests {
		for k, v := range m.layers {
			if names[k] < v {
				names[k] = v
			}
		}
	}
	var keys []string
	for k := range names {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	fmt.Println("  层名 → 清单体积（同名层取各版本中的最大值）：")
	for _, k := range keys {
		fmt.Printf("    %s%5d MiB\n", pad(k, 36), names[k])
	}
	fmt.Printf("  最值得盯的两层：Go SDK 底层 %d MiB vs 应用二进制层 %d MiB —— 比值 %d:1（清单现算）\n", single.layers["go SDK 底层(golang:1.22.5-bookworm)"], binMiB, single.layers["go SDK 底层(golang:1.22.5-bookworm)"]/binMiB)
	hdr(2, "四版 Dockerfile 文本（产物，落 homecube/deploy/docker/，逐个真打出来）")
	for _, m := range manifests {
		fmt.Printf("  ---- %s（tag：%s，共 %d 段 FROM）----\n", m.note, m.tag, strings.Count(m.text(), "\nFROM "))
		for _, ln := range strings.Split(m.text(), "\n") {
			fmt.Printf("  | %s\n", ln)
		}
	}
	hdr(3, "体积对照表：按清单求和、与单阶段做差（全部程序算）")
	fmt.Println("  " + pad("版本", 12) + pad("阶段数", 8) + pad("总体积", 12) + pad("较单阶段省", 12) + pad("省的比例", 10) + "运行时缺什么")
	for _, m := range manifests {
		t, save, ms := m.total(), single.total()-m.total(), []string{}
		if !m.has("CA 证书层") && strings.Contains(m.text()[strings.LastIndex(m.text(), "FROM "):], "scratch") {
			ms = append(ms, "CA 证书→出网 HTTPS 全挂")
		}
		if !m.has("tzdata 时区层") && strings.Contains(m.text()[strings.LastIndex(m.text(), "FROM "):], "scratch") {
			ms = append(ms, "tzdata→S11 家庭时区 LoadLocation 失败")
		}
		miss := "无"
		if len(ms) > 0 {
			miss = strings.Join(ms, "；")
		}
		fmt.Println("  " + pad(m.tag, 12) + pad(fmt.Sprint(strings.Count(m.text(), "\nFROM ")), 8) +
			pad(fmt.Sprintf("%d MiB", t), 12) + pad(fmt.Sprintf("%d MiB", save), 12) +
			pad(fmt.Sprintf("%d%%", save*100/single.total()), 10) + miss)
	}
	// 独立对账：做差得到的省量，必须等于「只在单阶段里的层之和 − 只在本版里的层之和」。
	onlySum := func(a, b manifest) int {
		s := 0
		for k, v := range a.layers {
			if !b.has(k) {
				s += v
			}
		}
		return s
	}
	for _, m := range manifests {
		if m.tag == "single" {
			continue
		}
		d1, d2 := single.total()-m.total(), onlySum(single, m)-onlySum(m, single)
		fmt.Printf("  对账 %-10s 做差=%d MiB，按层集合差=%d MiB，一致=%s\n", m.tag, d1, d2, yes[d1 == d2])
	}
	hdr(4, "CGO_ENABLED=0 与静态链接：本机真验的那一条（只打布尔与固定阈值）")
	ls, lstatic, lsize := probeStatic("linux")
	_, dstatic, _ := probeStatic("darwin")
	fmt.Printf("  本机 go build GOOS=linux CGO_ENABLED=0 成功：        %s\n", yes[ls])
	fmt.Printf("  linux 产物被 file 判定 statically linked：           %s\n", yes[lstatic])
	fmt.Printf("  本机 go build（darwin 原生）判定 statically linked：%s（Mach-O 无此字样，属形态差异）\n", yes[dstatic])
	fmt.Printf("  阈值对照：清单应用二进制层 %d MiB；探针二进制小于该阈值（真实字节数只参与内部比较，不打出来）：%s\n", binMiB, yes[ls && lsize < int64(binMiB)*1024*1024])
	fmt.Println(`  文本规则：CGO_ENABLED=0 时只用纯 Go 运行时，linux 产物静态链接、可扔进 scratch；
  一旦 CGO_ENABLED=1（走到 os/user、net 的 cgo 路径）产物动态链 glibc，scratch 里没有
  /lib 可加载、直接起不来——所以四版 Dockerfile 的 build 行都写了 CGO_ENABLED=0。镜像
  只跑 linux，本机 darwin 判 false 不说明构建错；『CGO=1 变动态』本机给不出 linux 动态
  ELF，列为真机复跑项（见第 6 节）。`)
	hdr(5, "红线自检：四版文本逐条过校验器（family_id/时区走配置、口令不进镜像）")
	checks := []struct {
		name, hint string
		hit        func(string) bool
	}{
		{"写死 family_id/时区（必须走配置注入）", "compose environment 给值，容器只读环境变量", func(t string) bool { return hasEnvWith(t, "FAMILY_ID=", "TZ=") }},
		{"明文口令进镜像", "口令走 .env/secrets，见 W58 d08", func(t string) bool { return hasEnvWith(t, "PASSWORD=", "SECRET=", "TOKEN=") }},
		{"金额常量烘进镜像", "金额只在数据库与接口里流动（*_cents 口径不变）", func(t string) bool { return strings.Contains(t, "_cents=") }},
	}
	for _, m := range manifests {
		nBad := 0
		for _, c := range checks {
			if c.hit(m.text()) {
				nBad++
				fmt.Printf("  ❌ %s 触发『%s』→ 正确做法：%s\n", m.tag, c.name, c.hint)
			}
		}
		if nBad == 0 {
			fmt.Printf("  ✅ %s：全部红线规则通过（共扫 %d 行文本 × %d 条规则）\n", m.tag, len(strings.Split(m.text(), "\n")), len(checks))
		}
	}
	hdr(6, "收口：本机验到哪 / 真环境要复跑哪几条")
	fmt.Printf("  本机已验：层清单求和与两条独立路径对账（第 3 节）、四版文本红线校验（第 5 节）、CGO_ENABLED=0\n  linux 产物静态链接判定=%s（第 4 节）。未调用 docker/nginx/psql。\n", yes[lstatic])
	fmt.Println("  真环境复跑（学员侧仓库根目录，Docker 守护进程起来之后）：")
	fmt.Println(`    1) docker build -f homecube/deploy/docker/Dockerfile.finance.single -t hc-fin-single .
    2) docker build -f homecube/deploy/docker/Dockerfile.finance.distroless -t hc-fin-dl .
    3) docker image ls --format '{{.Repository}} {{.Size}}'   # 对照第 3 节：量的是真实层
    4) docker history --no-trunc hc-fin-single                # SDK/模块缓存层为什么在
    5) docker run --rm hc-fin-scratch /svc-finance            # scratch 版报错=缺 CA/tz 的现场
    6) CGO_ENABLED=1 GOOS=linux go build -o probe ./cmd/svc-finance && file probe   # 动态那一侧
  明天（d02）：层顺序与版本固定——把『依赖层每次失效』的代价用层哈希算出来。`)
}

// W57 d02：可复现构建：层顺序、版本固定与缓存。
//
// Docker 缓存按「指令顺序 + 内容哈希」逐层命中：COPY . . 一旦打头，任何一次源码
// 改动都会让后面的 RUN go mod download 层整体失效——依赖层每次全量重做。今天要
// 把这种失效的代价用固定构建序列算出来（层哈希模拟命中率 × 每次重做的 MiB），并
// 产出版本固定（golang:1.22.5 而不是 latest）、依赖层先行、-ldflags=-buildid=、
// GOFLAGS/GOMODCACHE 处置都做对的 Dockerfile 正例与反例，交给逐条校验器点名。
// 本机无 Docker 守护进程（全程不调 docker/nginx/psql）：层哈希用 sha256 对「层内容
// 字符串」现算；浪费量按固定清单由程序求和做差；正/反例文本由行号级校验器逐条判定。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d02
// =====================================================================
package main

import (
	"crypto/sha256"
	"fmt"
	"strings"
)

var yes = map[bool]string{true: "是", false: "否"}

func hdr(n int, s string)          { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func linesOf(t string) []string    { return strings.Split(t, "\n") }
func miB(on bool, v int) int       { return map[bool]int{true: v}[on] }
func miS(on bool, s string) string { return map[bool]string{true: s}[on] }
func nulSep(r rune) bool           { return r == '\x00' }
func squeeze(s string) []string    { return strings.FieldsFunc(s, nulSep) }
func h12(s string) string          { h := sha256.Sum256([]byte(s)); return fmt.Sprintf("%x", h[:6]) }

// ---------- 层内容清单（MiB）：浪费量全部由程序按此求和/做差，不写死结论 ----------
const (
	modsMiB = 256 // RUN go mod download 那一层
	ctxMiB  = 12  // COPY . . 的构建上下文
	binMiB  = 18  // 应用二进制层（清单对照用，浪费量不含它）
)

// 第 2 节固定构建序列：这个月 6 次构建，各自改没改源码 / 改没改 go.mod+go.sum。
type evt struct {
	n        int
	src, mod bool
}

var evts = []evt{{1, false, false}, {2, true, false}, {3, true, false}, {4, false, true}, {5, true, false}, {6, false, false}}

// 两种层顺序在第 e 次构建时要重做的 MiB（依赖层是否失效，由失效规则决定）。
func costGood(e evt) int { return miB(e.mod, modsMiB) }
func costBad(e evt) int  { return miB(e.src || e.mod, modsMiB+ctxMiB) }

const goodDocker = `# homecube/deploy/docker/Dockerfile.finance —— 可复现构建：版本固定 + 依赖层先行
FROM golang:1.22.5-bookworm AS builder
WORKDIR /src
ENV CGO_ENABLED=0
ENV GOFLAGS=-mod=readonly
ENV GOMODCACHE=/go/pkg/mod
COPY go.mod go.sum ./
RUN go mod download
COPY . .
RUN go build -trimpath -ldflags "-s -w -buildid=" -o /out/svc-finance ./cmd/svc-finance

FROM alpine:3.20.3
RUN apk add --no-cache ca-certificates tzdata
COPY --from=builder /out/svc-finance /usr/local/bin/svc-finance
EXPOSE 8083
USER 65534:65534
ENTRYPOINT ["/usr/local/bin/svc-finance"]`
const badDocker = `# homecube/deploy/docker/Dockerfile.finance.bad —— 反例：latest + COPY . . 打头 + 明文口令
FROM golang:latest
WORKDIR /src
COPY . .
RUN go mod download
RUN go build -o /out/svc-finance ./cmd/svc-finance
ENV POSTGRES_PASSWORD=homecube-dev-2026
ENV TZ=Asia/Shanghai FAMILY_ID=fam-001
EXPOSE 8083
CMD ["/out/svc-finance"]`

// lineNo：sub 首次出现的行号（1 起）；找不到返回 -1。
func lineNo(t, sub string) int {
	i := strings.Index(t, sub)
	return map[bool]int{true: -1, false: 1 + strings.Count(t[:max(i, 0)], "\n")}[i < 0]
}
func isEnv(ln string) bool { return strings.HasPrefix(strings.TrimSpace(ln), "ENV ") }

// envHits：ENV 行里带任一禁串 → 点名行号与原文。
func envHits(t string, subs ...string) []string {
	out := []string{}
	for i, ln := range linesOf(t) {
		for _, s := range subs {
			if isEnv(ln) && strings.Contains(ln, s) {
				out = append(out, fmt.Sprintf("第 %d 行: %s（禁串 %s）", i+1, ln, s))
			}
		}
	}
	return out
}

type rule struct {
	name, advice string
	verdict      func(string) (bool, []string)
}

// hitVerdict：命中列表为空即通过的通用打包。
func hitVerdict(f func(string) []string) func(string) (bool, []string) {
	return func(t string) (bool, []string) { h := f(t); return len(h) == 0, h }
}

// tagBad：FROM 行不带冒号、或 :latest、或 tag 里没有小数点（没写死具体版本）。
func tagBad(ln string) bool {
	i := strings.Index(ln, ":")
	return i < 0 || strings.HasSuffix(ln, ":latest") || !strings.Contains(ln[max(i, 0)+1:], ".")
}
func badTagHits(t string) []string {
	out := []string{}
	for i, ln := range linesOf(t) {
		if strings.HasPrefix(ln, "FROM ") && tagBad(ln) {
			out = append(out, fmt.Sprintf("第 %d 行: %s", i+1, ln))
		}
	}
	return out
}
func orderVerdict(t string) (bool, []string) {
	iDep, iDl, iAll := lineNo(t, "COPY go.mod"), lineNo(t, "RUN go mod download"), lineNo(t, "COPY . .")
	if iDep > 0 && iDl > iDep && iAll > iDl {
		return true, []string{fmt.Sprintf("实测：COPY go.mod 第 %d 行 < go mod download 第 %d 行 < COPY . . 第 %d 行", iDep, iDl, iAll)}
	}
	return false, squeeze(miS(iDep < 0, "全文没有 COPY go.mod go.sum ./（依赖层没有独立内容）") + "\x00" +
		miS(iDep > iAll && iAll > 0, fmt.Sprintf("COPY . .（第 %d 行）排在 COPY go.mod（第 %d 行）之前——上下文先变，依赖层必失效", iAll, iDep)))
}
func buildidVerdict(t string) (bool, []string) {
	i := lineNo(t, "go build")
	ok := i > 0 && strings.Contains(linesOf(t)[i-1], "-buildid=")
	return ok, squeeze(miS(!ok, fmt.Sprintf("第 %d 行: %s", i, linesOf(t)[max(i, 1)-1])))
}
func missingEnvHits(t string) []string {
	return squeeze(miS(lineNo(t, "ENV GOFLAGS=") < 0, "全文缺少 ENV GOFLAGS=") + "\x00" +
		miS(lineNo(t, "ENV GOMODCACHE=") < 0, "全文缺少 ENV GOMODCACHE=") + "\x00" +
		miS(lineNo(t, "ENV CGO_ENABLED=0") < 0, "全文缺少 ENV CGO_ENABLED=0"))
}

var rules = []rule{
	{"① 版本固定：FROM 不许 :latest、tag 必须写死具体版本号", "改成 golang:1.22.5-bookworm / alpine:3.20.3；latest 会让同一份代码在不同日期构建出不同镜像", hitVerdict(badTagHits)},
	{"② 层顺序：先 COPY go.mod/go.sum 与 go mod download，再 COPY . .", "否则源码一改依赖层整体失效——第 2 节已经把代价算出来了", orderVerdict},
	{"③ 可复现：go build 的 -ldflags 里带 -buildid=", "buildid 把环境差异烘进二进制 → 两台机器字节不同、层哈希漂移、缓存与仓库去重全废", buildidVerdict},
	{"④ 明文口令不进镜像（ENV 不许带 PASSWORD=/SECRET=/TOKEN=）", "口令走 .env 或 secrets 挂载（W58 d08）；写进镜像就永远留在层历史里", hitVerdict(func(t string) []string { return envHits(t, "PASSWORD=", "SECRET=", "TOKEN=") })},
	{"⑤ family_id/时区不写死（ENV 不许带 TZ= / FAMILY_ID=）", "这两样是业务配置，运行期由 compose environment 注入，构建期不许烘死", hitVerdict(func(t string) []string { return envHits(t, "TZ=", "FAMILY_ID=") })},
	{"⑥ GOFLAGS/GOMODCACHE/CGO_ENABLED=0 三件写清", "GOFLAGS=-mod=readonly 防容器内悄悄改 go.mod；GOMODCACHE 显式路径才能挂缓存卷；CGO=0 保静态", hitVerdict(missingEnvHits)},
}

func report(r rule, tag, text string) bool {
	ok, hits := r.verdict(text)
	m := append(hits, "")
	fmt.Printf("    %s %s：%s\n", map[bool]string{true: "✅", false: "❌"}[ok], tag, map[bool]string{
		true:  "通过" + map[bool]string{true: "（" + m[0] + "）"}[len(hits) > 0],
		false: "违反，点名如下\n" + miS(len(hits) > 0, "       · "+strings.Join(hits, "\n       · ")+"\n") + "       建议：" + r.advice,
	}[ok])
	return ok
}
