// ---------- 数据：上游清单（compose 口径，端口只用这一处）+ 面目录 ----------
type upSvc struct {
	name string
	port int
}

var registry = []upSvc{{"finance", 8081}, {"calendar", 8082}, {"homeos", 8080}}

type facet struct {
	code string
	born bool // 本批是否启用；未启用的面连前缀都不该出现在配置里
}

var facets = []facet{
	{"finance.ledger", true}, {"finance.budget", true}, {"finance.report", true},
	{"finance.export", true}, {"homeos.panel", true}, {"lab.recipe", false},
}

func segOf(code string) string   { return strings.SplitN(code, ".", 2)[0] }
func prefixOf(seg string) string { return "/api/" + seg + "/" }
func atoi(s string) int          { n, _ := strconv.Atoi(s); return n }
func has(f []string, s string) bool {
	for _, x := range f {
		if x == s {
			return true
		}
	}
	return false
}

func portOf(name string) (int, bool) {
	for _, u := range registry {
		if u.name == name {
			return u.port, true
		}
	}
	return 0, false
}

// enabledSegs：本批启用、且段名真在上游清单里的服务段（排序后生成，保证确定性）
func enabledSegs() []string {
	set := map[string]bool{}
	for _, f := range facets {
		if _, ok := portOf(segOf(f.code)); f.born && ok {
			set[segOf(f.code)] = true
		}
	}
	var out []string
	for s := range set {
		out = append(out, s)
	}
	sort.Strings(out)
	return out
}

// ---------- 产物文本：由面目录生成，再故意改写造错配 ----------
const confHead = "# homecube/deploy/nginx/nginx.conf —— W57 d03 产物（本机不跑 nginx，只按字符串规则校验）"

type wreck struct{ mode, find, repl string } // sub 换所有命中行 / del 删首个命中行 / ins 在首个命中行后插一行

func conf(ws ...wreck) []string {
	segs := enabledSegs()
	ls := []string{confHead, "http {"}
	for _, s := range segs {
		p, _ := portOf(s)
		ls = append(ls, "    upstream "+s+" {", "        server "+s+":"+strconv.Itoa(p)+";", "    }")
	}
	ls = append(ls, "    server {", "        listen 80;")
	for _, s := range segs {
		ls = append(ls, "        location "+prefixOf(s)+" {", "            proxy_pass http://"+s+"/;", "        }")
	}
	ls = append(ls, "        location / {", "            return 404;", "        }", "    }", "}")
	for _, w := range ws {
		ls = apply(ls, w)
	}
	return ls
}

func apply(ls []string, w wreck) []string {
	out, done := []string{}, false
	for _, l := range ls {
		if w.mode == "sub" && strings.Contains(l, w.find) {
			out = append(out, strings.ReplaceAll(l, w.find, w.repl))
			continue
		}
		if w.mode == "del" && !done && strings.Contains(l, w.find) {
			done = true
			continue
		}
		out = append(out, l)
		if w.mode == "ins" && !done && strings.Contains(l, w.find) {
			out, done = append(out, w.repl), true
		}
	}
	return out
}

func show(ls []string) {
	for i, l := range ls {
		fmt.Printf("  %3d | %s\n", i+1, l)
	}
}

// ---------- 把文本解析回来 ----------
type locBlk struct { // 一个 location 块：前缀 + proxy_pass 原文 + 两处行号
	prefix     string
	regex      bool
	pass       string
	ln, passLn int
}

type upBlk struct { // 一个 upstream 块：名字 + server 行的 host:port + 两处行号
	name, host  string
	port        int
	upLn, srvLn int
}

func directive(t, name string) string {
	if !strings.HasPrefix(t, name+" ") {
		return ""
	}
	return strings.TrimSuffix(strings.TrimSpace(strings.TrimPrefix(t, name)), ";")
}

func parseLocs(ls []string) []locBlk {
	out := []locBlk{}
	for i := 0; i < len(ls); i++ {
		t := strings.TrimSpace(ls[i])
		if !strings.HasPrefix(t, "location ") || !strings.HasSuffix(t, "{") {
			continue
		}
		f := strings.Fields(t)
		lb := locBlk{ln: i + 1, regex: has(f, "~") || has(f, "~*")}
		for _, s := range f {
			if strings.HasPrefix(s, "/") {
				lb.prefix = s
			}
		}
		for j := i + 1; j < len(ls) && strings.TrimSpace(ls[j]) != "}"; j++ {
			if v := directive(strings.TrimSpace(ls[j]), "proxy_pass"); v != "" {
				lb.pass, lb.passLn = v, j+1
			}
		}
		out = append(out, lb)
	}
	return out
}

func parseUps(ls []string) []upBlk {
	out := []upBlk{}
	for i := 0; i+1 < len(ls); i++ {
		n := directive(strings.TrimSpace(ls[i]), "upstream")
		if n == "" || !strings.HasSuffix(strings.TrimSpace(ls[i]), "{") {
			continue
		}
		b := upBlk{name: strings.TrimSpace(strings.TrimSuffix(n, "{")), upLn: i + 1, srvLn: i + 2, host: "缺失"}
		if sv := directive(strings.TrimSpace(ls[i+1]), "server"); sv != "" {
			b.host, b.port = splitHost(sv)
		}
		out = append(out, b)
	}
	return out
}

func splitHost(s string) (string, int) {
	h, p := s, 0
	if i := strings.LastIndex(s, ":"); i > 0 {
		h, p = s[:i], atoi(s[i+1:])
	}
	return h, p
}

type passSpec struct {
	host string
	port int
	path string
}

func splitPass(v string) passSpec {
	v = strings.TrimPrefix(v, "http://")
	hp, path := v, ""
	if i := strings.Index(v, "/"); i >= 0 {
		hp, path = v[:i], v[i:]
	}
	h, p := splitHost(hp)
	return passSpec{h, p, path}
}

func upOf(ups []upBlk, name string) *upBlk {
	for i := range ups {
		if ups[i].name == name {
			return &ups[i]
		}
	}
	return nil
}

// ---------- 三处一致校验：前缀 ↔ 上游服务名 ↔ 端口 ----------
func threeWay(ls []string) int {
	ups, locs, bad := parseUps(ls), parseLocs(ls), 0
	say := func(s string) { fmt.Println(s); bad += strings.Count(s, "❌") }
	for _, l := range locs {
		if l.prefix == "/" {
			continue
		}
		seg := strings.Trim(strings.TrimPrefix(l.prefix, "/api/"), "/")
		ps := splitPass(l.pass)
		u := upOf(ups, ps.host)
		eff, from := ps.port, fmt.Sprintf("第 %d 行 proxy_pass 自带", l.passLn)
		if eff == 0 && u != nil {
			eff, from = u.port, fmt.Sprintf("第 %d 行 upstream server", u.srvLn)
		}
		want, inReg := portOf(seg)
		if !has(enabledSegs(), seg) { // 前缀本身就不该存在
			say(fmt.Sprintf("   ❌ 第 %d 行 location %s：服务段 %s 不在本批启用的面目录里 → 删掉整块，请求落到默认 404（不泄露这个面）", l.ln, l.prefix, seg))
		}
		if _, ok := portOf(ps.host); !ok {
			say(fmt.Sprintf("   ❌ 第 %d 行 proxy_pass http://%s：上游名 %s 不在清单 %s 里，最接近的是 %s → 应改成 http://%s/", l.passLn, ps.host, ps.host, regNames(), nearest(ps.host), seg))
		} else if !inReg {
			say(fmt.Sprintf("   ❌ 第 %d 行 location %s：前缀段 %s 自己就不在上游清单里 → 应改成已启用的前缀", l.ln, l.prefix, seg))
		} else if ps.host != seg {
			say(fmt.Sprintf("   ❌ 第 %d 行 proxy_pass http://%s%s：前缀段是 %s，上游却是 %s → 应改成 http://%s/（端口 %d）", l.passLn, ps.host, ps.path, seg, ps.host, seg, want))
		} else if !inReg {
			say("   ❌ 前缀段没有注册表端口可对")
		} else if eff != want || u == nil {
			say(fmt.Sprintf("   ❌ 第 %d 行 location %s：端口三处不一致——注册表 %d / 生效值 %d（来自%s）/ upstream 块 server %s:%d → 应统一改成 %d",
				l.ln, l.prefix, want, eff, from, seg, eff, want))
		} else {
			say(fmt.Sprintf("   ✅ %s：前缀段 %s = proxy_pass 上游 %s（第 %d 行）= 端口 %d（upstream 块第 %d 行 server %s:%d）",
				l.prefix, seg, ps.host, l.passLn, want, u.srvLn, u.host, u.port))
		}
	}
	return bad
}

func regNames() string {
	n := []string{}
	for _, u := range registry {
		n = append(n, u.name)
	}
	sort.Strings(n)
	return "[" + strings.Join(n, " ") + "]"
}

func nearest(s string) string { // 拼错时给最接近的清单名（编辑距离现算）
	best, bd := "无", 1<<30
	for _, u := range registry {
		if d := lev(s, u.name); d < bd {
			best, bd = u.name+"（距离 "+strconv.Itoa(d)+"）", d
		}
	}
	return best
}

func lev(a, b string) int {
	p := make([]int, len(b)+1)
	for j := range p {
		p[j] = j
	}
	for i := 1; i <= len(a); i++ {
		prev := p[0]
		p[0] = i
		for j := 1; j <= len(b); j++ {
			old := p[j]
			switch {
			case a[i-1] < b[j-1]:
				p[j] = min(prev, p[j]) + 1
			case a[i-1] > b[j-1]:
				p[j] = min(p[j], p[j-1]) + 1
			default:
				p[j] = prev
			}
			prev = old
		}
	}
	return p[len(b)]
}

// ---------- 语法自检（纯字符串规则，不跑 nginx） ----------
var dirs = []string{"server", "listen", "return", "proxy_pass", "client_max_body_size", "access_log"}

func syntax(ls []string) {
	for i, l := range ls {
		t := strings.TrimSpace(l)
		if t == "" || strings.HasPrefix(t, "#") || strings.HasSuffix(t, "{") || t == "}" || strings.HasSuffix(t, "\\") {
			continue
		}
		for _, d := range dirs {
			if strings.HasPrefix(t, d) && !strings.HasSuffix(t, ";") && strings.Count(t, " ") > 0 {
				fmt.Printf("   ❌ 第 %d 行「%s」缺分号 → 应改成 %s;\n", i+1, t, t)
			}
		}
	}
	depth, stack, neg := 0, []int{}, 0
	for i, l := range ls {
		for _, r := range l {
			if r == '{' {
				depth++
				stack = append(stack, i+1)
			} else if r == '}' {
				depth--
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				if depth < 0 && neg == 0 {
					neg = i + 1
				}
			}
		}
	}
	switch {
	case neg > 0:
		fmt.Printf("   ❌ 第 %d 行多出一个 }（此前 depth 已为 0）→ 大括号不配对\n", neg)
	case depth > 0:
		fmt.Printf("   ❌ 走到末尾 depth=%d：%d 个 { 只配了 %d 个 }，最内层还没闭合的 { 在第 %v 行 → 该补一个 }\n",
			depth, strings.Count(strings.Join(ls, ""), "{"), strings.Count(strings.Join(ls, ""), "}"), stack[len(stack)-1])
	case depth < 0:
		fmt.Printf("   ❌ 收尾时 depth=%d：多出一个 }\n", depth)
	default:
		fmt.Printf("   ✅ 大括号配对：%d 行文本走到底 depth=0\n", len(ls))
	}
	for _, l := range parseLocs(ls) { // 正则 location 里 proxy_pass 不许带 URI：起都起不来
		if l.regex && splitPass(l.pass).path != "" {
			fmt.Printf("   ❌ 第 %d 行正则 location + 第 %d 行 proxy_pass 带 URI 段「%s」→ 应去掉 URI 或改前缀匹配 location\n", l.ln, l.passLn, l.pass)
		}
	}
}

// ---------- proxy_pass 尾部斜杠：上游到底收到什么 URI（字符串运算得出） ----------
func upURI(prefix, pass, req string) string {
	base, q := req, ""
	if i := strings.Index(req, "?"); i >= 0 {
		base, q = req[:i], req[i:]
	}
	if p := splitPass(pass).path; p != "" {
		return p + strings.TrimPrefix(base, prefix) + q // 带 URI 段：前缀换成它
	}
	return base + q // 不带 URI 段：原始 URI 整条透传
}

// ---------- 404：路由不存在（反代层）vs 越权（业务层） ----------
func muxFor(ls []string, leak bool) http.Handler {
	m := http.NewServeMux()
	for _, l := range parseLocs(ls) {
		if l.prefix == "/" || l.pass == "" {
			continue
		}
		seg, pre := strings.Trim(strings.TrimPrefix(l.prefix, "/api/"), "/"), l.prefix
		m.HandleFunc(pre, func(w http.ResponseWriter, r *http.Request) {
			fmt.Fprintf(w, `{"svc":%q,"mounted_at":%q}`, seg, pre)
		})
	}
	// go1.22.5 的 ServeMux 没有 NotFound 字段（那是更高版本才有的可设字段），
	// 这里用默认 catch-all pattern "/" 兜住未注册路径：更长的 /api/{段}/ 前缀优先命中，
	// 剩下的（含 / 与未启用面前缀）一律落到这里返 404 —— 语义与 NotFound 一致。
	m.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNotFound)
		if leak { // 反例：把面清单写进 404 响应体
			codes := []string{}
			for _, f := range facets {
				codes = append(codes, f.code)
			}
			sort.Strings(codes)
			fmt.Fprintf(w, `{"error":"no_route","faces":["%s"]}`, strings.Join(codes, `","`))
			return
		}
		fmt.Fprint(w, `{"error":"no_route"}`) // 正例：不报面名、不报上游名、不报端口
	})
	return m
}

func hit(h http.Handler, path string) (int, string) {
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
	return rec.Code, rec.Body.String()
}

func leaks(body string) []string { // 未启用的面名出现在 404 响应体里 = 泄露
	out := []string{}
	for _, f := range facets {
		if !f.born && strings.Contains(body, f.code) {
			out = append(out, f.code)
		}
	}
	sort.Strings(out)
	return out
}

func biz(authed, sameFam bool, role string) int {
	switch {
	case !authed:
		return http.StatusUnauthorized // 401 你是谁
	case !sameFam:
		return http.StatusNotFound // 404 跨家庭：连「存在」都不承认
	case role != "owner":
		return http.StatusForbidden // 403 你够不上
	default:
		return http.StatusOK
	}
}

