// W57 d04：反代细节 —— 转发头与缓存策略
//
// nginx 站在三个 Go 服务前面，「转过去」不等于「转对」：客户端真实 IP 与协议只能靠
// 转发头传下去，头缺一个、多一段、或者被人自己塞一个，业务侧审计日志里的 client_ip
// 就是错的，限流失效、越权看不出来源；缓存头只要放错 location，「API 被缓存成旧账」和
// 「静态资源每次回源」会同时发生，而页面看着还正常。本机没装 nginx、Docker 守护进程也
// 没起，所以只做两件事：生成 location 正文逐行校验 + 用真 Go 代码验 header 读取语义。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d04
package main

import (
	"crypto/tls"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

const apiPrefix, attBytes, attCount, formBytes = "/api/finance/", 5 << 20, 3, 6 << 10 // 铁律⑥：单张 ≤5MB、一次 ≤3 张 + 表单余量
func sec(n int, t string)                                                             { fmt.Printf("\n===== %d. %s =====\n", n, t) }
func nOf(rep []string, sub string) int                                                { return strings.Count(strings.Join(rep, "|"), sub) }

func firstVal(v string) string { // XFF 是逗号列表、RemoteAddr 带 :port：两种都只取第一段
	return strings.FieldsFunc(v, func(r rune) bool { return r == ',' || r == ':' })[0]
}

var mk, sch = map[bool]string{true: "✅", false: "❌"}, map[bool]string{true: "https", false: "http"}
var blk, tlsOf = map[bool]string{true: "动态", false: "静态"}, map[bool]*tls.ConnectionState{true: &tls.ConnectionState{}}
var cc = []string{`add_header Cache-Control "no-store";`, `add_header Cache-Control "public, max-age=2592000, immutable";`} // [0] 归动态块，[1] 归静态块

// 产物：nginx location 正文（学员侧 homecube/deploy/nginx/locations.conf，本机不跑 nginx）。
const tmpl = `# homecube/deploy/nginx/locations.conf
location %s {
    proxy_pass http://$upstream_service;
    proxy_set_header Host              $host;
    proxy_set_header X-Forwarded-For   $remote_addr;
    proxy_set_header X-Forwarded-Proto $scheme;
    client_max_body_size %dm;
    %s
}
location /static/ {
    alias /usr/share/nginx/html/;
    expires 30d;
    %s
}`

func buildLocations(capMiB int, swapped bool) []string {
	k := map[bool]int{false: 0, true: 1}[swapped] // 反例版本：两块各拿别人的缓存头（行数不变，行号仍与第 1 节逐条对齐）
	return strings.Split(fmt.Sprintf(tmpl, apiPrefix, capMiB, cc[k], cc[1-k]), "\n")
}

// read 返回 (client_ip, scheme)：strict=false 是新手直觉（XFF 第一个值就是客户端），
// strict=true 只信反代白名单内的对端，并从右往左数 hops 个可信跳。
func read(r *http.Request, strict, trusted bool, hops int) (string, string) {
	xff, xfp := strings.Join(r.Header.Values("X-Forwarded-For"), ","), strings.Join(r.Header.Values("X-Forwarded-Proto"), "")
	p := strings.Split(strings.ReplaceAll(xff, " ", ""), ",")
	if xff == "" || (strict && !trusted) { // 头没发过来 / 对端不可信 → 只认直连地址
		p = []string{firstVal(r.RemoteAddr)}
	} else if strict && len(p) > hops {
		p = p[len(p)-hops:]
	}
	return firstVal(strings.Join(p, ",")), map[bool]string{true: xfp, false: sch[r.TLS != nil]}[xfp != "" && (!strict || trusted)]
}

func checkCache(lines []string) []string { // 动态块（反代到后端）只准 no-store，静态块必须长缓存
	out, dyn := []string{}, false
	for i, l := range lines {
		s := strings.TrimSpace(l)
		if strings.HasPrefix(s, "location") {
			dyn = strings.Contains(s, apiPrefix)
			out = append(out, fmt.Sprintf("   块起于第 %d 行：%s", i+1, s))
		} else if strings.HasPrefix(s, "expires") || strings.Contains(s, "Cache-Control") {
			out = append(out, fmt.Sprintf("   %s 第 %d 行 [%s块] %s", mk[strings.Contains(s, "no-store") == dyn], i+1, blk[dyn], s))
		}
	}
	return out
}

func report(name string, ls []string) int {
	rep := checkCache(ls)
	fmt.Printf("  %s：%d 个 location 块、%d 条缓存指令、错位 %d 处\n", name, nOf(rep, "块起于"), len(rep)-nOf(rep, "块起于"), nOf(rep, "❌"))
	for _, s := range rep {
		fmt.Println("  " + s)
	}
	if nOf(rep, "❌") > 0 { // 有放错块的版本顺带带行号重印，好逐条核对
		for i, l := range ls {
			fmt.Printf("%3d | %s\n", i+1, l)
		}
	}
	return nOf(rep, "❌")
}

func main() {
	sec(1, "生成 nginx location 正文（真打印；行号就是第 3 节校验用的行号）")
	need, capMiB := attBytes*attCount+formBytes, (attBytes*attCount+formBytes+(1<<20-1))/(1<<20) // 向上取整到 MiB：盖住业务需要又不放宽红线
	for i, l := range buildLocations(capMiB, false) {
		fmt.Printf("%3d | %s\n", i+1, l)
	}
	fmt.Printf("  client_max_body_size %dm = %d 字节 ≥ 业务需要 %d×%d+%d = %d 字节 → %s\n"+
		"  这个文件里没有任何 family_id、时区字面量：那些一律从服务配置/环境变量走。\n",
		capMiB, capMiB*(1<<20), attCount, attBytes, formBytes, need, mk[capMiB*(1<<20) >= need])
	sec(2, "服务读转发头的真 Go 代码：四种缺失组合各自读到什么")
	rows := []struct {
		name, peer, xff, xfp, conseq string
		secure, trusted              bool
	}{
		{"① 三个头都缺", "172.18.0.4:51234", "", "", "两种读法都只看到反代自己的地址 → client_ip 全错", false, true},
		{"② 只缺 X-Forwarded-For", "172.18.0.4:51234", "", "https", "漏了 XFF 那一行：scheme 保住，ip 退化成反代地址", true, true},
		{"③ 多值逗号列表（合法链）", "198.51.100.9:44320", "203.0.113.7, 198.51.100.9", "https", "浏览器→CDN→nginx 逐跳追加；取第一个值这次恰好对，前提是每个上游跳都诚实", true, true},
		{"④ 伪造值（绕过反代直连）", "203.0.113.7:39001", "8.8.8.8, 203.0.113.7", "https", "对端不在白名单却自带 XFF/XFP → naive 读到 8.8.8.8，限流键与审计日志被人牵着走", false, false},
	}
	fmt.Printf("  %-26s %-15s %-15s %-9s %-9s %s\n", "组合", "naive ip", "严格 ip", "naive协议", "严格协议", "判定")
	for _, c := range rows {
		r := httptest.NewRequest(http.MethodGet, sch[c.secure]+"://homecube.local"+apiPrefix+"v1/accounts", nil)
		r.RemoteAddr, r.TLS, r.Header["X-Forwarded-For"], r.Header["X-Forwarded-Proto"] = c.peer, tlsOf[c.secure], strings.Split(c.xff, ", "), strings.Split(c.xfp, ", ")
		ni, ns := read(r, false, c.trusted, 2)
		si, ss := read(r, true, c.trusted, 2)
		fmt.Printf("  %-26s %-15s %-15s %-9s %-9s %s\n", c.name, ni, si, ns, ss, mk[ni == si && ns == ss])
		fmt.Printf("      %s\n", c.conseq)
	}
	fmt.Println("  ①②：反代要覆盖式写 proxy_set_header X-Forwarded-For $remote_addr;（第 1 节第 5 行）\n  ③：合法链要从右往左数 2 跳才轮到真客户端。\n" +
		"  ④：对端不在反代白名单就整条丢弃 XFF/XFP，退回 RemoteAddr + r.TLS。")
	sec(3, "「API 不缓存 vs 静态长缓存」错位检查：先跑一致版，再跑注入错位版")
	report("一致版", buildLocations(capMiB, false))
	fmt.Printf("  —— 上面错位版已按行号重印全文，检出 %d 处放错块\n", report("注入错位版（动态块与静态块的缓存头互换）", buildLocations(capMiB, true)))
	fmt.Println("  本机已验：header 语义（真 Go + httptest 构造请求）、产物文本逐行规则、体积上限算术。\n" +
		"  本机没验：nginx 实际转发与真实 413 响应体（本机没装 nginx）。真机复跑：\n    nginx -t -c homecube/deploy/nginx/nginx.conf\n" +
		"    curl -sI https://<host>/api/finance/v1/accounts | grep -i cache-control  # 期望 no-store\n    curl -sI https://<host>/static/app.js | egrep -i 'cache-control|expires'  # 期望 public,max-age=2592000")
}

