code.content:
// W57 d05：健康检查与重启策略 —— 退出码决定重启次数
//
// compose 起来的那一分钟里 PostgreSQL 往往还没就绪，Go 进程连不上库怎么办？打一行日志再 exit
// 0 看着最体面，可 restart: on-failure 认定 0 是成功、从此不再拉起，服务一路红灯直到有人手动
// 重启；只有非零退出才触发退避重启。健康检查同理：scratch 里没有 shell 也没有 curl，探测只能调
// 自己的二进制；start_period 比冷启动还短就会被判 unhealthy。本机没 Docker 守护进程、没 nginx、没 PG，所以只生成文本逐字段对账 + 用固定模型算重启次数。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d05
package main

import (
	"fmt"
	"strconv"
	"strings"
)

const (
	bootSec, migrateSec, dbReadySec, humanSec, logsPerBoot = 2, 18, 60, 300, 6
	capGapSec, smokeWaitSec, hourSec, shortSP              = 30, 120, 3600, 5
)

type hc struct{ interval, timeout, startPeriod, retries int } // 四个字段的唯一来源，两份文本都由它生成
type run struct{ tries, ready, waited, logs int }

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string)           { fmt.Printf("\n===== %d. %s =====\n", n, t) }
func fixedGap(int) int              { return 1 }
func secs(v string) int             { n, _ := strconv.Atoi(strings.TrimSuffix(v, "s")); return n }
func rule(ok bool, s string) string { return fmt.Sprintf("   %s 规则 %s", mk[ok], s) }
func expGap(i int) int              { return min(1<<(i-1), capGapSec) } // Docker 重启退避：1s 起、逐次翻倍、封顶 30s

func simulate(gap func(int) int, exitZero bool) run { // 每次拉起耗时 bootSec；exit 0 时 on-failure 不再拉起，只能等人工巡检 humanSec
	t, n, w, lg := 0, 0, 0, 0
	for {
		n, t, lg = n+1, t+bootSec, lg+logsPerBoot
		if t += map[bool]int{true: humanSec, false: 0}[exitZero]; t >= dbReadySec || exitZero {
			return run{n, t, w, lg}
		}
		g := gap(n)
		t, w = t+g, w+g
	}
}

// 两份产物文本（学员侧仓库路径，本机不跑 docker）。
var tpls = []string{`# homecube/deploy/docker/Dockerfile.finance（runtime 段尾部）
FROM scratch
COPY --from=builder /out/finance /app/finance
HEALTHCHECK --interval=%ds --timeout=%ds --start-period=%ds --retries=%d \
  CMD ["/app/finance", "healthcheck"]`, `# homecube/deploy/compose.yaml（services.finance 片段）
    healthcheck:
      test: ["CMD", "/app/finance", "healthcheck"]
      interval: %ds
      timeout: %ds
      start_period: %ds
      retries: %d`}

func text(h hc, i int) []string {
	return strings.Split(fmt.Sprintf(tpls[i], h.interval, h.timeout, h.startPeriod, h.retries), "\n")
}
func show(ls []string) {
	for i, l := range ls {
		fmt.Printf("   %3d | %s\n", i+1, l)
	}
}

func field(ls []string, f string) (string, int) { // 取字段字面值与行号：Dockerfile 写 --start-period、compose 写 start_period，先归一化再找
	for i, l := range ls {
		u := strings.ReplaceAll(l, "-", "_")
		if k := strings.Index(u, f); k >= 0 {
			return strings.SplitN(strings.Trim(u[k+len(f):], "=: "), " ", 2)[0], i + 1
		}
	}
	return "缺失", 0
}

func audit(d, c []string) int { // 逐字段比对两份文本 + 四条规则，边打印边数 ❌
	nv := func(f string) int { v, _ := field(c, f); return secs(v) }
	it, to, sp, rt := nv("interval"), nv("timeout"), nv("start_period"), nv("retries")
	cold, win, bad := bootSec+migrateSec, it*rt, 0
	say := func(s string) { fmt.Println(s); bad += strings.Count(s, "❌") }
	for _, f := range []string{"interval", "timeout", "start_period", "retries"} {
		dv, dl := field(d, f)
		cv, cl := field(c, f)
		say(fmt.Sprintf("   %s %-12s Dockerfile 第 %d 行 %-5s / compose 第 %d 行 %-5s%s", mk[dv == cv], f, dl, dv, cl, cv, map[bool]string{true: "", false: "  ← 两份文本不一致"}[dv == cv]))
	}
	say(rule(to < it, fmt.Sprintf("timeout %ds 必须 < interval %ds：探测不许自己顶掉自己", to, it)))
	say(rule(sp >= cold, fmt.Sprintf("start_period %ds 必须 ≥ 冷启动 %ds（boot %d + 迁移 %d）；这个窗口内的失败不计入 retries，只给进程起死回生的时间", sp, cold, bootSec, migrateSec)))
	say(rule(win <= smokeWaitSec, fmt.Sprintf("最坏检出窗 interval×retries = %ds 必须 ≤ 冒烟脚本等待上限 %ds", win, smokeWaitSec)))
	say(rule(strings.Contains(strings.Join(c, " "), `"CMD",`), "test 用 CMD 数组：scratch 没有 shell，CMD-SHELL 探测必然失败"))
	return bad
}

func main() {
	sec(1, "生成 HEALTHCHECK 与 compose healthcheck 两份文本，逐字段对账")
	h := hc{interval: 30, timeout: 3, startPeriod: 20, retries: 3}
	d, c := text(h, 0), text(h, 1)
	show(d)
	show(c)
	fmt.Println("  上面两份文本：scratch 里没有 /bin/sh 也没有 curl，探测只能调自己的二进制子命令。下面逐字段比对 + 四条规则（一致版）：")
	audit(d, c)
	fmt.Println("  语义分工：liveness 由 HEALTHCHECK 判（进程死透 → daemon 拉起）；readiness 由退出码判（连不上库就非零退出 → 交给 on-failure 退避）—— 第 2 节算给你看。")
	bad := text(hc{interval: h.interval, timeout: 35, startPeriod: shortSP, retries: h.retries}, 1) // 只把 compose 那份手滑改坏
	fmt.Println("  只改坏 compose（timeout 写 35s、start_period 写 5s），同一套检查重跑：")
	show(bad)
	fmt.Printf("  当场检出 %d 处 ❌：两份文本不一致的两处都点名到了行号，规则也各挂一条。\n", audit(d, bad))

	sec(2, "exit 0 vs 非零退出：把重启次数、不可用时长、日志量算出来")
	fmt.Printf("  模型假设（固定不变，两次跑出同一张表）：每次拉起耗时 %ds，PostgreSQL 第 %d 秒才就绪；\n"+
		"  退出码 0 时 on-failure 认为是成功、不再拉起 → 只能等人工巡检，假设第 %d 秒才发现。\n", bootSec+migrateSec, dbReadySec, humanSec)
	seq, sum := []string{}, 0
	for i := 1; i <= 6; i++ {
		seq, sum = append(seq, fmt.Sprint(expGap(i))), sum+expGap(i)
	}
	fmt.Printf("  指数退避前 6 项（秒）：%s…（第 7 项起被上限 %ds 盖住）→ 合计 %ds\n", strings.Join(seq, " "), capGapSec, sum)
	zero, base, fixed := simulate(expGap, true), simulate(expGap, false), simulate(fixedGap, false)
	fmt.Printf("  %-26s %-6s %6s %8s %8s %6s %s\n", "变体", "退出码", "拉起", "就绪于", "退避累计", "日志行", "与 B 就绪差")
	fmt.Printf("  %-26s %-6s %6d %7ds %7ds %6d %+d\n", "A 连不上库就 exit 0", "0", zero.tries, zero.ready, zero.waited, zero.logs, zero.ready-base.ready)
	fmt.Printf("  %-26s %-6s %6d %7ds %7ds %6d %+d\n", "B 非零退出 + 指数退避", "1", base.tries, base.ready, base.waited, base.logs, base.ready-base.ready)
	fmt.Printf("  %-26s %-6s %6d %7ds %7ds %6d %+d\n", "C 非零退出 + 退避写死 1s", "1", fixed.tries, fixed.ready, fixed.waited, fixed.logs, fixed.ready-base.ready)
	fmt.Printf("  A 那 +%d 秒里日志只有 %d 行：没有任何东西在重试，只能等人看见。\n  库真挂满 1 小时：B 稳态拉起 %d 次（%d÷(%d+%d)），C 要 %d 次 → 多 %d 次；C 早 %ds 就绪，换来约 %d 倍的重启量和 %d 行日志。\n",
		zero.ready-base.ready, zero.logs, hourSec/(capGapSec+bootSec), hourSec, capGapSec, bootSec, hourSec/(1+bootSec), hourSec/(1+bootSec)-hourSec/(capGapSec+bootSec), base.ready-fixed.ready, (hourSec/(1+bootSec))/(hourSec/(capGapSec+bootSec)), fixed.logs)
	fmt.Printf("  第 1 节那个 start_period=%ds 的后果：每轮 = 检出窗 %ds + 冷启动 %ds → %ds 观察窗内被重启 %d 次，每次都在连上库之前被判死，重启计数一路涨但服务从没 ready 过。\n", shortSP, h.interval*h.retries, bootSec+migrateSec, humanSec, humanSec/(h.interval*h.retries+bootSec+migrateSec))

	sec(3, "本机验到什么程度 / 真机要复跑哪几条（交 W58）")
	fmt.Println("  本机已验：两份健康检查文本由同一组字段生成再逐条对账（含改坏版的检出）、四条规则的算术、重启次数与不可用时长全部由 simulate 现算。\n" +
		"  本机没验：Docker 守护进程没起，unhealthy 的真实判定时序、RestartCount 是否真在涨、CMD 探测能否在 scratch 里执行，一条都没跑过。\n" +
		"  真环境复跑清单（W58 d07 起全套、d12 逐条勾；本程序只列不执行）：\n    1) docker compose up -d --build finance\n    2) docker inspect -f '{{.State.Health.Status}} {{.RestartCount}}' homecube-finance-1  # 期望 healthy / 0\n" +
		"    3) docker stop -t 0 homecube-postgres-1; docker inspect -f '{{.State.ExitCode}}' homecube-finance-1  # 期望非 0\n    4) sleep 90; docker inspect -f '{{.RestartCount}}' homecube-finance-1  # 期望在涨，增速符合退避\n" +
		"    5) docker compose up -d postgres; docker compose ps  # 期望 postgres healthy 后 finance 自己回来")
}

// W57 d06：W57 收口 —— Dockerfile 与 nginx.conf 的跨文件对账
//
// 这两份产物由两个人维护：镜像里的 LABEL 是服务对自己运行契约的自述，nginx.conf 是运维写的
// 站点配置。只要抄漏一处 —— proxy_pass 指到 8081、location 少一个字母、/healthz 写成 /health、
// 时区图省事写进 ENV TZ —— 站点照样起来，切镜像时 502、探测假绿、真故障时日志时间轴对不上。
// 本机没有 Docker 守护进程、没有 nginx、没有 PG，所以走「生成 + 静态校验」：程序同时生成两份
// 文本，端口、服务名、前缀、时区、健康检查路径五处逐字对账，任何一处不一致当场点名行号。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d06
package main

import (
	"fmt"
	"strings"
)

var want = map[string]string{"service": "finance", "prefix": "/api/finance/", "port": "8080", "health": "/healthz", "tz": "HOMEUBE_TIMEZONE"}
var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string)                    { fmt.Printf("\n===== %d. %s =====\n", n, t) }
func nginxText(o map[string]string) []string { return fill(nginxTmpl, o) }
func trim(v string) string                   { return strings.TrimPrefix(v, "homecube-") } // nginx 写 homecube-<服务>，LABEL 只写服务名：比之前各削一次前缀
func pick(bad, def string) string            { return map[bool]string{true: def, false: bad}[bad == ""] }

func fill(t string, o map[string]string) []string { // 五个 token 都从 want 取；覆盖项 o 只可能改坏其中一处
	for _, k := range []string{"service", "prefix", "port", "health", "tz"} {
		t = strings.ReplaceAll(t, "$"+k, pick(o[k], want[k]))
	}
	return strings.Split(t, "\n")
}
func dockerText(o map[string]string) []string { // o["hardTZ"] 是反例开关：图省事把时区写死进镜像（踩红线），配置键就此从 Dockerfile 消失
	return fill(map[bool]string{true: strings.Replace(dockerTmpl, "LABEL io.homecube.timezone=$tz", "ENV TZ=Asia/Shanghai", 1), false: dockerTmpl}[o["hardTZ"] != ""], o)
}
func pair(side string, o map[string]string) ([]string, []string) { // 错只落在被点名的那一份里，另一份仍由 want 生成
	d, n := dockerText(nil), nginxText(o)
	if side == "docker" {
		d, n = dockerText(o), nginxText(nil)
	}
	return d, n
}
func show(ls []string) {
	for i, l := range ls {
		fmt.Printf("  %3d | %s\n", i+1, l)
	}
}
func grab(ls []string, mark string) (string, string) { // 取 marker 之后到空格/分号的那个 token 并带上行号；没命中就直说没有
	for i, l := range ls {
		if k := strings.Index(l, mark); k >= 0 {
			return strings.TrimRight(strings.SplitN(l[k+len(mark):], " ", 2)[0], `";`), fmt.Sprintf("第 %d 行", i+1)
		}
	}
	return "（没这个键）", "这一份里没有"
}

// 两份产物文本（学员侧仓库路径）。镜像的 LABEL 逐条自述运行契约，nginx 里服务名与端口各出现两次，
// 两边都由同一张 want 表填出来 —— 所以「一致」是被生成的，不是被抄的；对账要逐字验它有没有抄漏。
var dockerTmpl = `# homecube/deploy/docker/Dockerfile.$service（多阶段：builder → scratch）
FROM golang:1.22.5-alpine AS builder
WORKDIR /src
COPY go.mod go.sum ./
RUN go mod download
COPY . .
RUN CGO_ENABLED=0 GOOS=linux go build -trimpath -ldflags=-buildid= -o /out/app ./cmd/$service
FROM scratch
COPY --from=builder /out/app /app/$service
LABEL io.homecube.service=$service
LABEL io.homecube.route-prefix=$prefix
LABEL io.homecube.listen-port=$port
LABEL io.homecube.health-path=$health
LABEL io.homecube.timezone=$tz
EXPOSE $port
HEALTHCHECK --interval=30s --timeout=3s --start-period=20s --retries=3 CMD ["/app/$service", "healthcheck"]`

var nginxTmpl = `# homecube/deploy/nginx/homecube.conf（W57 站点片段）
upstream homecube_$service { server homecube-$service:$port; }
server {
    listen 443 ssl;
    server_name homecube.local;
    set $upstream_service homecube-$service;
    location $prefix { proxy_set_header Host $host; proxy_pass http://$upstream_service:$port; }
    location = $health { proxy_pass http://$upstream_service:$port$health; access_log off; }
    # 时区同源：两份产物都只引用配置键 $tz，值由 compose 注入，部署文本里不许出现时区字面量
}`

func audit(d, n []string, brief bool) int { // 五处跨文件逐字对账 + 四条红线扫描，边打印边数 ❌
	bad := 0
	say := func(s string) {
		bad += strings.Count(s, "❌")
		if !brief || strings.Contains(s, "❌") {
			fmt.Println(s)
		}
	}
	for _, p := range []struct{ name, dm, nm string }{
		{"端口", "io.homecube.listen-port=", "$upstream_service:"}, {"服务名", "io.homecube.service=", "$upstream_service "}, {"前缀", "io.homecube.route-prefix=", "location "}, {"时区", "io.homecube.timezone=", "配置键 "}, {"健康检查路径", "io.homecube.health-path=", "location = "},
	} {
		dv, dl := grab(d, p.dm)
		nv, nl := grab(n, p.nm)
		say(fmt.Sprintf("   %s %-12s 镜像自述 %s %-13s nginx %s %-13s%s", mk[trim(dv) == trim(nv)], p.name, dl, trim(dv), nl, trim(nv),
			map[bool]string{true: "", false: "  ← 两处不一致"}[trim(dv) == trim(nv)]))
	}
	for _, lit := range []struct{ lit, name string }{{"Asia/", "时区不许写死"}, {"+08", "UTC 偏移不许写死"}, {"family_id", "family_id 不进部署文本"}, {"password", "明文口令不进产物"}} {
		_, dl := grab(d, lit.lit)
		_, nl := grab(n, lit.lit)
		hits := strings.Count(strings.Join(d, "|"), lit.lit) + strings.Count(strings.Join(n, "|"), lit.lit)
		say(fmt.Sprintf("   %s 红线 %-16s 命中 %d 处 %s", mk[hits == 0], lit.name, hits,
			map[bool]string{true: "", false: "→ 镜像 " + dl + " / nginx " + nl}[hits == 0]))
	}
	return bad
}

func main() {
	sec(1, "同时生成两份产物：Dockerfile（镜像自述 LABEL）与 nginx.conf（站点配置）")
	d, n := dockerText(nil), nginxText(nil)
	show(d)
	show(n)

	sec(2, "跨文件对账：端口 / 服务名 / 前缀 / 时区 / 健康检查路径 —— 先跑一致版")
	bad := audit(d, n, false)
	fmt.Printf("  五处逐字一致 %d/5 ✅、四条红线 0 命中 → 这两份产物才允许交给 W58 去起真环境。\n", 5-bad)

	sec(3, "五处各注入一个错（每次只改一处），逐个看检出证据")
	for _, b := range []struct{ name, side, key, val, why string }{
		{"端口", "nginx", "port", "8081", "proxy_pass 指到 8081，镜像自述还是 8080"},
		{"服务名", "nginx", "service", "financ", "服务名少一个字母，compose 网络里根本解析不到"},
		{"前缀", "nginx", "prefix", "/api/fin/", "location 写成 /api/fin/，服务注册的前缀是 /api/finance/"},
		{"时区", "docker", "hardTZ", "1", "镜像里写死 ENV TZ，配置键从 Dockerfile 消失（踩红线）"},
		{"健康检查路径", "nginx", "health", "/health", "nginx 探 /health，镜像自述的健康路径是 /healthz"},
	} {
		fmt.Printf("  —— 注入「%s」：%s\n", b.name, b.why)
		dd, nn := pair(b.side, map[string]string{b.key: b.val})
		fmt.Printf("     检出 %d 处 ❌，其余四处仍逐字一致 —— 检查是点对点的，一处抄漏不会把五处都标红。\n", audit(dd, nn, true))
	}

	sec(4, "本机验到什么程度 / 真机要复跑哪五条（交 W58，本程序一条都不执行）")
	fmt.Println("  本机已验：两份产物由同一张 want 表生成，五处取值各自从文本里抓回来逐字比（比的是文本不是内存变量，" +
		"所以抄漏一处当场就点名行号），再加四条红线扫描。\n  本机没验：镜像能不能跑起来、探测命令能不能在 scratch 里执行、" +
		"nginx 能不能解析到服务名 —— Docker 守护进程没起、没 nginx、没 PG，本程序一个字都没执行。真环境复跑五条：\n" +
		"    1) docker build -f homecube/deploy/docker/Dockerfile.finance -t homecube/finance:0.5.0 homecube/server\n" +
		"    2) docker compose -f homecube/deploy/compose.yaml up -d --wait  # 四个服务都转 healthy 才算起完\n" +
		"    3) docker exec homecube-nginx-1 nginx -t -c /etc/nginx/nginx.conf  # 语法与路径自检\n" +
		"    4) curl -si http://127.0.0.1:8080/api/finance/v1/accounts | head -1  # 期望 401/200，不是 404/502\n" +
		"    5) docker compose logs --since 1m nginx finance | grep -E 'GET /api/finance'  # 前缀与状态码都要对得上")
}

// W58 d07：compose 的依赖图 —— 四个服务怎么摆
//
// finance / calendar / postgres / nginx 四个服务写进 compose.yaml 不难，难在两处：一、depends_on
// 只保证「上游容器起过」，不保证「就绪」——只写它，起套后第一波请求全 503；二、名字散在 compose 与
// nginx 两处（服务名、容器名、网络名、端口、镜像 tag），改一处漏两处，站点照样起得来，只是 DNS 不
// 通、探测假绿。本机 Docker CLI 在但守护进程没起、没 nginx、没 PG：所以这个程序只做「生成文本产物 +
// 静态校验」——registry 是名字与端口的单一来源，两份文本由它逐行生成，再把文本里每一处引用扫回来
// 对着 registry 逐个解析；503 时序用钉死的常数当场算。一条 docker/nginx 命令都不执行。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d07
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type svc struct {
	key, container, image, port, prefix string
	deps                                []string
}

// registry：四个受管服务 + homeos 平台面（compose 外先起、只挂进同一网络）——名字/端口/tag 的唯一来源
var managed = []svc{
	{"postgres", "homecube-postgres", "postgres:16.4-alpine", "5432", "", nil},
	{"finance", "homecube-finance", "homecube/finance:0.5.0", "8080", "/api/finance/", []string{"postgres"}},
	{"calendar", "homecube-calendar", "homecube/calendar:0.5.0", "8081", "/api/calendar/", []string{"postgres"}},
	{"nginx", "homecube-nginx", "nginx:1.27.3-alpine", "80", "", []string{"finance", "calendar"}},
}
var homeos = svc{"homeos", "homecube-homeos", "compose 外先起", "8082", "/api/homeos/", nil}

const (
	network   = "homecube-net"
	volume    = "homecube-pgdata"
	aggPrefix = "/api/home/" // homeos 承载的聚合入口前缀（S12 d21），与 /api/homeos/ 同上游
	coldSec   = 20           // 应用冷启动 = boot 2 + 迁移 18（W57 d05 同源常数）
	dbReady   = 60           // PostgreSQL 可接受连接的时刻（d05 同源）
	pgProbe   = 30           // 健康探测节奏（d05：interval 30s）
	waveFrom  = 10           // 第一波请求：第 10 秒起
	waveStep  = 5            // 每 5 秒一条
	waveN     = 18           // 共 18 条（打到第 95 秒）
)

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }
func show(ls []string) {
	for i, l := range ls {
		fmt.Printf("   %3d | %s\n", i+1, l)
	}
}
func svcByKey(k string) (svc, bool) {
	for _, s := range managed {
		if s.key == k {
			return s, true
		}
	}
	return svc{}, false
}
func all() []svc { return append(append([]svc{}, managed...), homeos) }
func known(v string) bool {
	for _, s := range all() {
		if s.container == v {
			return true
		}
	}
	return false
}
func portOf(v string) string {
	for _, s := range all() {
		if s.container == v {
			return s.port
		}
	}
	return "?"
}
func hasHC(ls []string, key string) bool { // condition: service_healthy 的前提：目标服务块里真有 healthcheck:
	lo, hi := -1, len(ls)
	for i, l := range ls {
		if l == "  "+key+":" {
			lo = i
			continue
		}
		if lo >= 0 && i > lo && strings.HasPrefix(l, "  ") && !strings.HasPrefix(l, "   ") && strings.HasSuffix(l, ":") {
			hi = i
			break
		}
	}
	if lo < 0 {
		return false
	}
	for _, l := range ls[lo:hi] {
		if strings.TrimSpace(l) == "healthcheck:" {
			return true
		}
	}
	return false
}

// 产物①：compose.yaml —— 全部字段取自 registry；b 是三个「手滑注入口」（第 4 节反证用）
func composeText(b map[string]string) []string {
	o := []string{
		"# homecube/deploy/compose.yaml —— W58 d07 四服务全套；名字/端口/tag 全部由程序 registry 生成",
		"name: homecube",
		fmt.Sprintf("x-homecube-external-surfaces: # %s 平台面在本 compose 之外先起，只挂进同一网络；反代仍按前缀分流", homeos.key),
		fmt.Sprintf("  %s: {dns: %s, port: %s, prefix: %s}", homeos.key, homeos.container, homeos.port, homeos.prefix),
		"services:",
	}
	pg, _ := svcByKey("postgres")
	for _, s := range managed {
		o = append(o, "  "+s.key+":", "    image: "+s.image+" # tag 钉死，不用 latest（W57 d02）", "    container_name: "+s.container)
		if len(s.deps) > 0 {
			o = append(o, "    depends_on:")
			for _, d := range s.deps {
				t := d
				if b["dep"] != "" && s.key == "finance" {
					t = b["dep"] // 注入口：把这一处 depends_on 目标写成容器名
				}
				o = append(o, "      "+t+":", "        condition: service_healthy # 只写 depends_on＝只等「起过」不等「就绪」（第 5 节时序表）")
			}
		}
		switch s.key {
		case "postgres":
			o = append(o, "    environment:", "      POSTGRES_USER: homecube", "      POSTGRES_DB: homecube",
				"      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?走 .env 与 secrets，明文不进这份文本（d08 专管）}")
		case "finance", "calendar":
			host, up := pg.container, strings.ToUpper(s.key)
			if b["dsn"] != "" {
				host = b["dsn"]
			}
			o = append(o, "    environment:",
				fmt.Sprintf("      %s_PORT: %q", up, s.port),
				fmt.Sprintf("      %s_DB_DSN: postgres://homecube:${POSTGRES_PASSWORD}@%s:%s/homecube?sslmode=disable&TimeZone=${HOMEUBE_TIMEZONE}", up, host, pg.port),
				"      HOMEUBE_TIMEZONE: ${HOMEUBE_TIMEZONE:?时区从配置走，不进 compose 字面量（W57 d06 同源规矩）}")
		}
		switch s.key {
		case "nginx":
			o = append(o, "    ports:", `      - "80:80"`, `      - "443:443"`, "    volumes:", "      - ./nginx/homecube.conf:/etc/nginx/conf.d/homecube.conf:ro")
		case "postgres":
			o = append(o, "    volumes:", "      - "+volume+":/var/lib/postgresql/data")
		default:
			p := s.port
			if b["expose"] != "" {
				p = b["expose"]
			}
			o = append(o, "    expose: ["+strconv.Quote(p)+"]")
		}
		switch s.key {
		case "postgres":
			o = append(o, "    healthcheck:", `      test: ["CMD-SHELL", "pg_isready -U homecube -d homecube"]`)
		case "nginx":
			o = append(o, "    healthcheck:", `      test: ["CMD", "wget", "-q", "--spider", "http://127.0.0.1/healthz"]`)
		default:
			o = append(o, "    healthcheck:", fmt.Sprintf(`      test: ["CMD", "/app/%s", "healthcheck"]`, s.key))
		}
		sp := map[string]string{"postgres": "30s", "nginx": "10s", "finance": "20s", "calendar": "20s"}[s.key]
		o = append(o, "      interval: 30s", "      timeout: 3s", "      start_period: "+sp, "      retries: 3", "    restart: on-failure", "    networks: ["+network+"]")
	}
	return append(o, "volumes:", "  "+volume+":", "networks:", "  "+network+":", "    name: "+network)
}

// 产物②：nginx 分流片段（W58 版骨架；转发头与缓存策略归 W57 d03/d04，这里不重复）
func nginxText(b map[string]string) []string {
	o := []string{"# homecube/deploy/nginx/homecube.conf —— W58 d07 版；前缀↔上游名↔端口三处由 registry 生成",
		"server {", "    listen 80; # 443 ssl 段沿用 W57 d06 片段", "    location = /healthz { return 200 \"ok\\n\"; access_log off; }"}
	for i, s := range all() {
		if s.prefix == "" {
			continue
		}
		up, port := s.container, s.port
		if i == len(all())-1 { // homeos 行
			up, port = homeos.container, homeos.port
		}
		if b["up"] != "" && s.key == "calendar" {
			up = b["up"]
		}
		if b["upPort"] != "" && s.key == "calendar" {
			port = b["upPort"]
		}
		src := map[bool]string{true: "受管容器", false: "compose 外先起（x- 已声明）"}[s.key != homeos.key]
		o = append(o, fmt.Sprintf("    location %s { proxy_pass http://%s:%s; } # 上游：%s（%s）", s.prefix, up, port, s.key, src))
		if s.key == homeos.key { // homeos 还承载首页聚合入口（S12 d21：首屏唯一业务请求 /api/home/summary）
			o = append(o, fmt.Sprintf("    location %s { proxy_pass http://%s:%s; } # 上游：%s 的聚合入口（同容器同端口）", aggPrefix, homeos.container, homeos.port, s.key))
		}
	}
	if b["lab"] != "" {
		o = append(o, "    location /api/lab/ { proxy_pass http://homecube-calendar:8081; } # 注入口：未声明面混进来")
	}
	return append(o, "    location / { root /srv/homecube/web; try_files $uri $uri/ /index.html; }", "}")
}

type ref struct {
	ln   int
	file string
	kind string
	got  string
	ok   bool
	why  string
}

func scan(c, n []string) []ref { // 把两份文本里每一处「名字/端口引用」抠出来，现场对着 registry 判定
	var rs []ref
	cur, inDep := "", false
	for i, l := range c {
		t := strings.TrimSpace(l)
		if strings.HasPrefix(l, "  ") && !strings.HasPrefix(l, "   ") && strings.HasSuffix(t, ":") && !strings.Contains(t, " ") {
			cur = strings.TrimSuffix(t, ":")
		}
		if inDep && !strings.HasPrefix(l, "      ") {
			inDep = false
		}
		if t == "depends_on:" {
			inDep = true
		}
		switch {
		case inDep && strings.HasPrefix(l, "      ") && strings.HasSuffix(t, ":") && !strings.Contains(t, " "):
			k := strings.TrimSuffix(t, ":")
			rs = append(rs, ref{i + 1, "compose", "depends_on 目标", k, isSvc(k) && hasHC(c, k),
				map[bool]string{true: "服务名存在且目标带 healthcheck", false: "depends_on 认的是服务名不是容器名；service_healthy 还要求目标有健康检查"}[isSvc(k)]})
		case strings.HasPrefix(t, "container_name:"):
			v := strings.TrimSpace(strings.SplitN(t, ":", 2)[1])
			rs = append(rs, ref{i + 1, "compose", "容器名", v, cur != "" && v == containerOf(cur), "必须等于 registry 里 " + cur + " 的容器名"})
		case strings.Contains(t, "_DB_DSN:"):
			h := ""
			if j := strings.Index(t, "@"); j >= 0 {
				h = strings.SplitN(t[j+1:], ":", 2)[0]
			}
			rs = append(rs, ref{i + 1, "compose", "DSN 主机", h, h == containerOf("postgres"), "DSN 只许指受管 postgres 容器（口令段是 ${POSTGRES_PASSWORD} 引用→d08）"})
		case strings.HasPrefix(t, "expose: ["):
			p := strings.Trim(strings.TrimSuffix(strings.TrimPrefix(t, "expose: ["), "]"), `"'`)
			s, ok := svcByKey(cur)
			rs = append(rs, ref{i + 1, "compose", "对外端口", p, ok && p == s.port, "expose 必须等于 registry 端口"})
		case strings.HasPrefix(t, "networks: ["):
			v := strings.TrimSuffix(strings.TrimPrefix(t, "networks: ["), "]")
			rs = append(rs, ref{i + 1, "compose", "网络名", v, v == network, "所有服务 networks 必须同一来源：" + network})
		}
	}
	for i, l := range n {
		if k := strings.Index(l, "location "); k >= 0 {
			f := strings.Fields(l[k:])
			pf := f[1]
			if pf == "=" && len(f) > 2 {
				pf = f[2] // location = /healthz 的精确匹配写法
			}
			if pf != "/healthz" && pf != "/" { // 业务前缀必须来自 registry：未声明的面混进 location＝违零请求红线
				in := pf == aggPrefix // homeos 聚合入口也算已声明（x- 段之外的第二条路由，S12 d21）
				for _, s := range all() {
					if s.prefix == pf {
						in = true
					}
				}
				rs = append(rs, ref{i + 1, "nginx", "前缀 " + pf, pf, in, "location 的业务前缀必须是 registry 声明过的面；未声明面（如 /api/lab/）客户端零请求（S12 d09）"})
			}
		}
		if j := strings.Index(l, "proxy_pass http://"); j >= 0 && !strings.Contains(l, "127.0.0.1") {
			tk := strings.SplitN(l[j+len("proxy_pass http://"):], ";", 2)[0]
			ps := strings.SplitN(tk, ":", 2)
			up, port := ps[0], "?"
			if len(ps) > 1 {
				port = ps[1]
			}
			pf := "？"
			if k := strings.Index(l, "location "); k >= 0 {
				pf = strings.Fields(l[k:])[1]
			}
			rs = append(rs, ref{i + 1, "nginx", "上游 " + pf, up + ":" + port, known(up) && port == portOf(up),
				map[bool]string{true: "名字与端口都对上 registry", false: "名字未登记或端口漂移（该名字登记端口是 " + portOf(up) + "）"}[known(up)]})
		}
	}
	return rs
}
func known2(k string) bool { return isSvc(k) }
func isSvc(k string) bool  { _, ok := svcByKey(k); return ok }
func containerOf(k string) string {
	s, ok := svcByKey(k)
	if !ok {
		return ""
	}
	return s.container
}

func report(rs []ref) int {
	bad := 0
	for _, r := range rs {
		fmt.Printf("   %s %-14s %s 第 %2d 行  引用 %-24s %s\n", mk[r.ok], r.kind, r.file, r.ln, r.got, r.why)
		if !r.ok {
			bad++
		}
	}
	return bad
}

// 第一波 18 条请求的时序（常数钉死）：nginxUp＝nginx 开始接听的时刻，readyAt＝finance 上游就绪的时刻
func firstWave(nginxUp, readyAt int) (refused, s503, s200 int) {
	for i := 0; i < waveN; i++ {
		t := waveFrom + i*waveStep
		switch {
		case t < nginxUp:
			refused++ // nginx 还没起：连接层被拒，不会有假响应
		case t < readyAt:
			s503++ // nginx 起了但上游没就绪：503 是 nginx 亲手回的
		default:
			s200++
		}
	}
	return
}

