// —— 扫描器：三条结构规则，命中就给行号与建议 ——
type rule struct {
	name string
	// 对一行给判定：hit=是否引用了这个名字, bad=是否违规
	test func(l string) (bool, string)
}

var reKey = regexp.MustCompile(`(PASSWORD|SECRET|TOKEN)[A-Z_]*\s*[:=]\s*(\S.*)$`)
var reURL = regexp.MustCompile(`://[^:/@\s]+:([^@\s]+)@`)
var rePort = regexp.MustCompile(`- "5432:5432"`)

func isPlaceholder(v string) bool { // ${引用、__占位__、<尖角>、带 :? 报错语义的 ${VAR:?} 都算安全写法
	v = strings.TrimSpace(v)
	return strings.HasPrefix(v, "${") || strings.HasPrefix(v, "__") || strings.HasPrefix(v, "<") || strings.Contains(v, ":?")
}
func ruleSecret(l string) (bool, string) {
	m := reKey.FindStringSubmatch(l)
	if m == nil {
		return false, ""
	}
	key := strings.NewReplacer(" ", "", "\t", "").Replace(strings.SplitN(strings.TrimSpace(l), ":", 2)[0])
	key = strings.SplitN(key, "=", 2)[0]
	if strings.HasSuffix(key, "_FILE") && strings.HasPrefix(strings.TrimSpace(m[2]), "/run/secrets/") {
		return true, "" // _FILE 约定：文件路径本身不是秘密，秘密在被 ignore 的文件里
	}
	if isPlaceholder(m[2]) {
		return true, ""
	}
	return true, "口令/密钥键写了字面量 → 改 ${POSTGRES_PASSWORD:?} 引用或 secrets 文件；这行现在是「把钥匙贴在门上」"
}
func ruleURL(l string) (bool, string) {
	m := reURL.FindStringSubmatch(l)
	if m == nil {
		return false, ""
	}
	if isPlaceholder(m[1]) {
		return false, ""
	}
	return true, "DSN 内嵌明文口令 → 口令段必须是 ${POSTGRES_PASSWORD} 引用，拼装见第 4 节"
}
func rulePortPub(l string) (bool, string) {
	if !rePort.MatchString(l) {
		return false, ""
	}
	return true, "postgres 端口发布到宿主机 → 库只进 compose 网络（expose/内网），对外面只有 nginx 的 80/443（d07）"
}

func scan(ls []string, tag string) (int, [3]int) {
	var per [3]int
	rules := []rule{{"R1 明文口令键", ruleSecret}, {"R2 DSN 内嵌口令", ruleURL}, {"R3 库端口外露", rulePortPub}}
	for i, l := range ls {
		for ri, r := range rules {
			hit, why := r.test(l)
			if why == "" {
				if hit {
					fmt.Printf("   %s %s %s 第 %d 行：引用了该类键，走的是 ${}/占位符/_FILE 写法 → 放行\n", mk[true], r.name, tag, i+1)
				}
				continue
			}
			fmt.Printf("   %s %s %s 第 %d 行：%s\n%s原行：%s\n", mk[false], r.name, tag, i+1, why, "      ", l)
			per[ri]++
		}
	}
	return per[0] + per[1] + per[2], per
}

// —— DSN 参数表：每段的值与含义（值从拼装函数现取，不手写结论） ——
func dsn(tz, pw, host string) string {
	return fmt.Sprintf("postgres://homecube:%s@%s:5432/homecube?sslmode=disable&TimeZone=%s", pw, host, tz)
}
func paramOf(s, key string) string { // 从 DSN 文本里把参数现值抠出来——判定与展示读的都是文本，不是入参
	j := strings.Index(s, key+"=")
	if j < 0 {
		return "（没有这一段）"
	}
	return strings.SplitN(strings.SplitN(s[j+len(key)+1:], "&", 2)[0], " ", 2)[0]
}
func auditDSN(s string) int {
	bad := 0
	rows := []struct {
		name string
		ok   bool
		val  string
		why  string
	}{
		{"主机段", strings.Contains(s, "@"+pgDns+":"), strings.SplitN(strings.SplitN(s, "@", 2)[1], ":", 2)[0], "只认 d07 容器名：127.0.0.1 在容器里指「自己」，指不到库"},
		{"口令段", func() bool { m := reURL.FindStringSubmatch(s); return m != nil && isPlaceholder(m[1]) }(), reURL.FindStringSubmatch(s)[1], "必须是 ${POSTGRES_PASSWORD} 引用（第 2 节 R2）"},
		{"sslmode", paramOf(s, "sslmode") == "disable", paramOf(s, "sslmode"), "显式写死并给理由（compose 内网）而不是吃驱动默认"},
		{"时区段", paramOf(s, "TimeZone") == "${HOMEUBE_TIMEZONE}", paramOf(s, "TimeZone"), "呼应 S11：报表切桶按家庭时区；呼应 S13：列是 TIMESTAMPTZ，会话时区只影响显示"},
	}
	for _, r := range rows {
		fmt.Printf("   %s %-8s 值 %-24s %s\n", mk[r.ok], r.name, r.val, r.why)
		if !r.ok {
			bad++
		}
	}
	return bad
}

