// W58 d09：卷、网络与独立启停 —— 删卷的破坏面要能数出来，降级路径要能算出来
//
// 命名卷与 bind mount 的差别不在「能不能跑」，在「数据归谁管、备份点在哪、down -v 会不会连坐」。
// 库数据只活在 homecube-pgdata 一个命名卷里——删卷等于删账，破坏面必须用行数与 *_cents 总额数出来，
// 而不是口头强调。另一半：finance 与 calendar 两个业务服务必须能独立启停（S13 判据⑤的部署版）：
// 停一个，另一个的面照常，home/summary 只把坏区标 degraded（S12 d21 的契约），整页不 500。
// 本机没有 Docker 守护进程、没有 PG：只生成 compose 卷/网络片段文本 + 结构校验 + 用钉死模型现算
// 行数与降级表；docker/pg_dump/psql 一条都不执行。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d09
package main

import (
	"fmt"
	"strings"
)

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }
func show(tag string, ls []string) {
	fmt.Println("  " + tag)
	for i, l := range ls {
		fmt.Printf("   %3d | %s\n", i+1, l)
	}
}

// —— 产物：compose 的卷与网络片段（学员侧 homecube/deploy/；b 为注入口） ——
func composeFrag(b map[string]string) []string {
	vol, ro, net := "homecube-pgdata", ":ro", "homecube-net"
	if b["vol"] != "" {
		vol = b["vol"]
	}
	if b["ro"] == "drop" {
		ro = ""
	}
	if b["net"] != "" {
		net = b["net"]
	}
	return []string{
		"# homecube/deploy/compose.yaml（d09 片段：卷与网络的唯一声明处）",
		"services:",
		"  postgres:",
		"    volumes:",
		"      - " + vol + ":/var/lib/postgresql/data # 命名卷：数据归 Docker 管，归备份策略管",
		"    networks: [" + net + "]",
		"  nginx:",
		"    volumes:",
		"      - ./nginx/homecube.conf:/etc/nginx/conf.d/homecube.conf" + ro + " # bind mount：仓库里的配置文件，只读挂载",
		"    networks: [" + net + "]",
		"volumes:",
		"  homecube-pgdata: # ← 全库数据只活在这一处；删它 = 删账（第 3 节数给你看）",
		"networks:",
		"  " + net + ":",
		"    name: " + net,
	}
}

// 卷语义的模型：两种挂载在各生命周期动作下的存亡（动作→结果由模型函数判，不手写结论）
func namedAlive(action string) bool { return action != "down -v" }

// bind mount 的文件源在仓库里：compose 的任何动作（down/down -v 也不例外）都删不到它，
// 能删到它的只有仓库自身的变更——所以配置走 git 版本控制、库走命名卷＋pg_dump。
func bindAlive(string) bool { return true }

func inter(a, b []string) []string { // 两面交集：独立启停的前提，交集由双重循环现数
	var o []string
	for _, x := range a {
		for _, y := range b {
			if x == y {
				o = append(o, x)
			}
		}
	}
	return o
}

// —— 卷内数据的账本（演示夹具：行数与 *_cents 总额是输入数据，合计与破坏面全部由程序求和） ——
var ledger = []struct {
	table  string
	rows   int
	cents  int64 // 该表金额列合计（分）；无金额列为 0
	softOK bool  // 是否走软删（deleted_at 可恢复）
}{
	{"finance_account", 1280, 0, true},
	{"finance_transaction", 58432, 2145678900, true},
	{"finance_budget", 64, 12345600, true},
	{"finance_budget_period", 256, 9876500, false},
	{"calendar_due_registration", 220, 0, true},
	{"homeos_notification", 410, 0, true},
	{"homeos_family_module", 30, 0, true},
	{"homeos_family_settings", 12, 0, false},
}

// —— 面 → 服务 → home/summary 区 的依赖表（单一来源；降级表由它现算） ——
type face struct{ code, svc, section string }

var faces = []face{
	{"ledger", "finance", "账目摘要"}, {"budget", "finance", "账目摘要"}, {"report", "finance", "账目摘要"},
	{"export", "finance", ""}, {"reminder", "calendar", "待办提醒"},
	{"notification", "homeos", "通知未读"}, {"activity", "homeos", "最近动态"}, {"settings", "homeos", ""},
}

func facesOf(svc string) []string {
	var o []string
	for _, f := range faces {
		if f.svc == svc {
			o = append(o, f.code)
		}
	}
	return o
}
func degrade(running map[string]bool) (degraded []string, avail []string, page int) {
	seen := map[string]bool{}
	for _, f := range faces {
		if running[f.svc] {
			avail = append(avail, f.code)
			continue
		}
		if f.section != "" && !seen[f.section] {
			seen[f.section] = true
			degraded = append(degraded, f.section)
		}
	}
	page = 200 // nginx 与 homeos 都不在「可停」集合里：整页永远 200，坏只坏区（S12 d21 契约）
	return
}

// —— 静态校验：卷/网络引用的结构规则 ——
func audit(ls []string, brief bool) int {
	bad := 0
	say := func(s string) {
		bad += strings.Count(s, "❌")
		if !brief || strings.Contains(s, "❌") {
			fmt.Println(s)
		}
	}
	declared := false
	used := map[string]bool{}
	for i, l := range ls {
		t := strings.TrimSpace(l)
		switch {
		case strings.HasPrefix(t, "homecube-pgdata:"):
			declared = true
		case strings.HasPrefix(t, "- homecube-pgdata:/"):
			used["pg"] = true
		case strings.HasPrefix(t, "- "):
			if v := strings.SplitN(t[2:], ":", 2)[0]; v != "homecube-pgdata" && !strings.HasPrefix(v, "./") {
				say(fmt.Sprintf("   ❌ 第 %d 行 引用卷 %s：未在顶层 volumes: 声明的卷名（改名要两处同步，这里只容得下声明过的）", i+1, v))
			}
			if strings.HasPrefix(t[2:], "./") {
				if strings.Contains(t, "/var/lib/postgresql") {
					say(fmt.Sprintf("   ❌ 第 %d 行 库数据目录被 bind 进仓库路径：数据进 git 的诱惑，红线（库必须走命名卷）", i+1))
				}
				if !strings.Contains(t, ":ro") {
					say(fmt.Sprintf("   ❌ 第 %d 行 bind mount 缺 :ro：仓库文件挂进容器必须只读，反代配置不该被进程改写", i+1))
				}
			}
		case strings.HasPrefix(t, "networks: ["):
			v := strings.TrimSuffix(strings.TrimPrefix(t, "networks: ["), "]")
			say(fmt.Sprintf("   %s 第 %d 行 网络引用 %s：与顶层声明 %s 同源", mk[v == "homecube-net"], i+1, v, "homecube-net"))
		}
	}
	say(fmt.Sprintf("   %s 卷声明：pgdata 被服务引用=%v、顶层声明=%v（两处都必须有，少一处要么挂不上要么起不来）",
		mk[declared && used["pg"]], used["pg"], declared))
	return bad
}

