func fileName(t tbl, dir string) string {
	return fmt.Sprintf("homecube/deploy/migrations/%s/%05d_%s_%s.sql", dirOf(t.name), t.num, t.name, dir)
}
func dirOf(name string) string {
	for _, p := range []string{"finance", "calendar", "homeos"} {
		if strings.HasPrefix(name, p) {
			return p
		}
	}
	return "homeos"
}

// 每条 up / down 的 SQL 文本（由 tables 生成；b 是注入口）
func upSQL(t tbl, b map[string]string) []string {
	o := []string{fmt.Sprintf("-- %s（重复执行安全 = 幂等；已跑过的环境永不回头改它，改名/改列都新写一号）", fileName(t, "up"))}
	kw := "CREATE TABLE IF NOT EXISTS "
	if b["noINE"] == t.name {
		kw = "CREATE TABLE " // 注入口：幂等性破了
	}
	o = append(o, kw+"finance."+t.name+" ("+t.cols+");")
	if dirOf(t.name) != "finance" { // 表名与 schema 同源：非 finance 域挂自己的 schema
		o[1] = strings.Replace(o[1], "finance.", dirOf(t.name)+".", 1)
	}
	for _, ix := range t.idx {
		k := ix
		if b["noIdxINE"] == t.name {
			k = strings.Replace(ix, "INDEX IF NOT EXISTS", "INDEX", 1)
		}
		o = append(o, k+";")
	}
	return o
}
func downSQL(t tbl, b map[string]string) []string {
	kw := "DROP TABLE IF EXISTS "
	if b["noIE"] == t.name {
		kw = "DROP TABLE "
	}
	return []string{fmt.Sprintf("-- %s", fileName(t, "down")), kw + dirOf(t.name) + "." + t.name + ";"}
}

var reRef = regexp.MustCompile(`REFERENCES ([a-z_.]+)\(`)
var reCents = regexp.MustCompile(`([a-z_]+_cents) ([a-zA-Z0-9]+)`)

func audit(b map[string]string, brief bool) int {
	bad := 0
	say := func(s string) {
		bad += strings.Count(s, "❌")
		if !brief || strings.Contains(s, "❌") {
			fmt.Println(s)
		}
	}
	// A 编号连续
	okNums := true
	for i, t := range tables {
		if t.num != i+1 {
			okNums = false
		}
	}
	say(fmt.Sprintf("   %s A 编号 %d..%d 连续无跳号（%d 个号 %d 张表）", mk[okNums], tables[0].num, tables[len(tables)-1].num, len(tables), len(tables)))
	// B 配对与反序
	downSeq := make([]int, 0, len(tables))
	for i := len(tables) - 1; i >= 0; i-- {
		downSeq = append(downSeq, tables[i].num)
	}
	miss := []string{}
	for _, t := range tables {
		if b["missDown"] == t.name {
			miss = append(miss, fmt.Sprintf("0000%d(%s)", t.num, t.name))
		}
	}
	say(fmt.Sprintf("   %s B 每条 up 都有配对 down（缺 %d 条%s）；down 执行序 %s＝up 序 %s 的倒影",
		mk[len(miss) == 0], len(miss), map[bool]string{true: "", false: "：" + strings.Join(miss, " ")}[len(miss) == 0], fmt.Sprint(downSeq), fmt.Sprint(upNums())))
	// C 幂等：所有 CREATE/DROP 语句带 IF [NOT] EXISTS
	nNo := 0
	for _, t := range tables {
		for _, l := range upSQL(t, b) {
			if (strings.HasPrefix(l, "CREATE TABLE ") || strings.HasPrefix(l, "CREATE INDEX ") || strings.HasPrefix(l, "CREATE UNIQUE INDEX ")) && !strings.Contains(l, "IF ") {
				say(fmt.Sprintf("   ❌ C 幂等破了：%s 缺 IF NOT EXISTS（%s 重复执行会炸）", t.name, fileName(t, "up")))
				nNo++
			}
		}
		for _, l := range downSQL(t, b)[1:] {
			if strings.HasPrefix(l, "DROP TABLE ") && !strings.Contains(l, "IF EXISTS") {
				say(fmt.Sprintf("   ❌ C 幂等破了：%s 的 down 缺 IF EXISTS（%s 在「没这张表」的环境重放会报错停住）", t.name, fileName(t, "down")))
				nNo++
			}
		}
	}
	if nNo == 0 {
		say(fmt.Sprintf("   %s C 幂等：全部 DDL 带 IF [NOT] EXISTS，重跑安全", mk[true]))
	}
	// D 依赖顺序：REFERENCES 目标表必须出生在前
	seen := map[string]bool{}
	okD := true
	for _, t := range tables {
		for _, m := range reRef.FindAllStringSubmatch(strings.Join(upSQL(t, b), "\n"), -1) {
			tblName := m[1]
			if i := strings.LastIndex(m[1], "."); i >= 0 {
				tblName = m[1][i+1:] // 去掉 schema 前缀，认表名
			}
			if !seen[tblName] {
				say(fmt.Sprintf("   ❌ D 依赖顺序：%s REFERENCES %s——被引用表还没出生", t.name, m[1]))
				okD = false
			}
		}
		seen[t.name] = true
	}
	if okD {
		say(fmt.Sprintf("   %s D 依赖顺序：REFERENCES 全部指向已出生表（流水→账户、期→预算）", mk[true]))
	}
	// E 索引在表之后（同文件内 CREATE TABLE 先于 index 行）
	okE := true
	for _, t := range tables {
		ls := upSQL(t, b)
		firstIdx := -1
		for i, l := range ls {
			if strings.HasPrefix(l, "CREATE ") && strings.Contains(l, "INDEX") {
				firstIdx = i
				break
			}
		}
		if firstIdx >= 0 && !strings.HasPrefix(ls[firstIdx-1], "CREATE TABLE") && firstIdx != 2 {
			okE = false
		}
	}
	say(fmt.Sprintf("   %s E 索引顺序：每个 up 文件里 index 行都排在 CREATE TABLE 之后", mk[okE]))
	// F 列契约：family_id NOT NULL；软删表两列齐；写表带 client_request_id；*_cents 全 BIGINT
	okF, okG, okH, okI := true, true, true, true
	for _, t := range tables {
		if !strings.Contains(t.cols, "family_id uuid NOT NULL") {
			okF = false
		}
		if t.soft && !(strings.Contains(t.cols, "deleted_at") && strings.Contains(t.cols, "deleted_by")) {
			okG = false
		}
		if t.write && !strings.Contains(t.cols, "client_request_id uuid NOT NULL") {
			okH = false
		}
		for _, m := range reCents.FindAllStringSubmatch(t.cols, -1) {
			if m[2] != "bigint" {
				say(fmt.Sprintf("   ❌ I *_cents 类型：%s.%s 是 %s，必须 bigint（分是整数，S3 起的老规矩）", t.name, m[1], m[2]))
				okI = false
			}
		}
	}
	say(fmt.Sprintf("   %s F family_id：七张表全部 NOT NULL 起步（每条查询恒带，S12 红线）", mk[okF]))
	say(fmt.Sprintf("   %s G 软删配对：软删表 deleted_at+deleted_by 齐（有 deleted_at 没 deleted_by＝删了不知道谁删的，恢复路径断）", mk[okG]))
	say(fmt.Sprintf("   %s H 幂等写：面向用户的写落库表（账户/流水/预算/通知/面开关）都带 client_request_id NOT NULL；到期登记靠 (source_system,source_id,kind) 唯一键兜幂等、预算期行是服务事务内插——两者不在此列", mk[okH]))
	say(fmt.Sprintf("   %s I *_cents：所有分单位列都是 bigint", mk[okI]))
	return bad
}
func upNums() []int {
	var o []int
	for _, t := range tables {
		o = append(o, t.num)
	}
	return o
}

// 执行时机模型：3 副本 × 8 号迁移 × 每号 3s；advisory lock 把并发压成串行（数值由函数现算）
func sim(variant string) (err, dup, doneAt int) {
	replicas, per := 3, 3
	n := len(tables)
	switch variant {
	case "A": // 启动即迁移，无锁：三个副本同时抢每个号，version 行 2 次唯一键冲突
		return (replicas - 1) * n, (replicas - 1) * n, n * per
	case "B": // 启动即迁移 + pg_advisory_lock：串行，最后一个副本等满前两个
		return 0, 0, replicas * n * per
	case "C": // 发布前一次性迁移 Job：单跑者迁移完（n*per），副本只管起（2s）
		return 0, 0, n*per + 2
	}
	return
}

