// W58 d11：迁移的数据安全 —— 改表结构与红线
//
// d10 管「迁移文件本身齐不齐」，这一天管「迁移动了什么」：加列可以随便加；改类型必须先回填再收紧
// （未回填的 ALTER TYPE/SET NOT NULL 会在半路把老行的 NULL 冻成约束事故）；删列等于丢账——
// amount/balance/occurred_at/client_request_id/family_id/软删列都是账本列，只允许「先停写→读切换→
// 隔一个发布号再删孤儿旧列」的两阶段路径。*_cents 必须 bigint、必须 NOT NULL、金额列不许 DEFAULT 0
// （把没记的说成零花费＝假成功）。软删列（deleted_at+deleted_by）的迁移顺序与恢复路径也要静态查：
// 恢复 SQL 不带 family_id＝跨家庭误恢复，踩 404 红线。本机没有 PG：全部走「生成迁移对 + 语句序
// 逐条静态校验」，psql/EXPLAIN 只出现在真环境复跑清单里。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d11
package main

import (
	"fmt"
	"strings"
)

type mig struct {
	file      string
	stmts     []string
	down      []string
	generated bool // 反例注入用
}

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }
func show(tag string, ls []string) {
	fmt.Println("  " + tag)
	for i, l := range ls {
		fmt.Printf("   %3d | %s\n", i+1, l)
	}
}

// d10 已跑过的迁移里，本卡必须「续存」的两条硬事实（静态清单，检查按名字回指）
var carried = []string{
	"CREATE INDEX IF NOT EXISTS idx_fin_txn_fam_time ON finance.finance_transaction (family_id, occurred_at) WHERE deleted_at IS NULL",
	"ALTER TABLE finance.finance_transaction ADD COLUMN amount_cents bigint (00009 起回填)",
}

func safeMigrations() []mig {
	return []mig{
		{"00008_txn_add_note", []string{
			"ALTER TABLE finance.finance_transaction ADD COLUMN IF NOT EXISTS note varchar(200);",
		}, []string{
			"ALTER TABLE finance.finance_transaction DROP COLUMN IF EXISTS note; -- note 不在账本列清单里，可逆",
		}, false},
		{"00009_txn_amount_to_cents", []string{
			"ALTER TABLE finance.finance_transaction ADD COLUMN IF NOT EXISTS amount_cents bigint;",
			"UPDATE finance.finance_transaction SET amount_cents = amount * 100 WHERE amount_cents IS NULL; -- 回填先行（真机分批 5 万行/批，别一把长锁）",
			"ALTER TABLE finance.finance_transaction ALTER COLUMN amount_cents SET NOT NULL; -- 回填完成才收紧约束",
			"CREATE INDEX IF NOT EXISTS idx_txn_cents_type ON finance.finance_transaction (family_id, amount_cents);",
		}, []string{
			"DROP INDEX IF EXISTS finance.idx_txn_cents_type;",
			"ALTER TABLE finance.finance_transaction ALTER COLUMN amount_cents DROP NOT NULL; -- down 不删列：数据还在被读",
		}, false},
		{"00010_retire_amount_column（阶段 B）", []string{
			"-- 阶段 A（上一个发布）：停写旧列 amount、读路径全量切到 amount_cents——发布事项，不在 DDL 里",
			"ALTER TABLE finance.finance_transaction DROP COLUMN IF EXISTS amount; -- 孤儿旧列，两阶段的第二刀",
		}, []string{
			"-- 不配 down：删掉的旧列数据已无处回填，恢复=从备份重放（这条注释本身就是检查项）",
		}, false},
		{"00011_notif_soft_delete", []string{
			"ALTER TABLE homeos.homeos_notification ADD COLUMN IF NOT EXISTS deleted_at timestamptz;",
			"ALTER TABLE homeos.homeos_notification ADD COLUMN IF NOT EXISTS deleted_by uuid;",
			"CREATE INDEX IF NOT EXISTS idx_notif_soft ON homeos.homeos_notification (family_id) WHERE deleted_at IS NULL;",
			"-- 恢复路径（应用层 SQL，family_id 恒带——跨家庭误恢复＝泄露，404 红线的部署版）",
			"UPDATE homeos.homeos_notification SET deleted_at = NULL, deleted_by = NULL WHERE id = $1 AND family_id = $2;",
		}, []string{
			"-- down 不删软删列：列上可能正挂着恢复期数据，要删另起发布号并先出「零引用」审计",
		}, false},
	}
}

// 红线清单：这些列出现在 DROP COLUMN 里＝丢账
var ledgerCols = []string{"amount_cents", "balance_cents", "used_cents", "occurred_at", "client_request_id", "family_id", "deleted_at", "deleted_by", "source_system", "source_id", "kind"}

func isDropColumn(l string) (col string, ok bool) {
	if !strings.Contains(l, "DROP COLUMN") {
		return "", false
	}
	f := strings.Fields(l)
	for i, x := range f {
		if x == "EXISTS" && i+1 < len(f) {
			return strings.TrimRight(f[i+1], ";"), true
		}
	}
	return "", true
}

func audit(ms []mig, brief bool) int {
	bad := 0
	say := func(s string) {
		bad += strings.Count(s, "❌")
		if !brief || strings.Contains(s, "❌") {
			fmt.Println(s)
		}
	}
	allText := strings.Join(carried, "\n")
	for _, m := range ms {
		allText += strings.Join(m.stmts, "\n")
	}
	// R1 改类型/收紧约束必须先回填
	for _, m := range ms {
		for i, l := range m.stmts {
			tighten := (strings.Contains(l, "ALTER COLUMN") && strings.Contains(l, " TYPE ")) ||
				(strings.Contains(l, "SET NOT NULL") && strings.Contains(l, "_cents"))
			if !tighten {
				continue
			}
			col := "amount_cents"
			backfilled := false
			for j := 0; j < i; j++ {
				if strings.Contains(m.stmts[j], "UPDATE") && strings.Contains(m.stmts[j], "SET "+col) {
					backfilled = true
				}
			}
			say(fmt.Sprintf("   %s R1 回填先行：%s 第 %d 行 %s 之前%s", mk[backfilled], m.file, i+1,
				map[bool]string{true: "SET NOT NULL", false: "ALTER TYPE"}[strings.Contains(l, "SET NOT NULL")],
				map[bool]string{true: "有 UPDATE 回填", false: "没有任何回填——老行的 NULL 当场把迁移冻住"}[backfilled]))
		}
		// R2 删列 = 丢账
		for i, l := range m.stmts {
			col, ok := isDropColumn(l)
			if !ok || strings.HasPrefix(strings.TrimSpace(l), "--") {
				continue
			}
			hit := false
			for _, c := range ledgerCols {
				if c == col {
					hit = true
				}
			}
			if hit {
				say(fmt.Sprintf("   ❌ R2 删列＝丢账：%s 第 %d 行 DROP COLUMN %s 是账本列。正解只有两阶段：先停写、读切换跑满一个周期，再另号删孤儿旧列", m.file, i+1, col))
			} else if col == "amount" { // 孤儿旧列：只有「阶段 A 已停写」的文件里允许
				phaseA := strings.Contains(strings.Join(m.stmts, "\n"), "停写旧列")
				say(fmt.Sprintf("   %s R2 删列审查：%s 第 %d 行删的是旧列 amount（阶段 A 停写标记 %v，两阶段才放行）", mk[phaseA], m.file, i+1, phaseA))
			}
		}
		// R5 软删列序：index 引用 deleted_at 必须排在该列出生之后
		for i, l := range m.stmts {
			if strings.Contains(l, "CREATE INDEX") && strings.Contains(l, "deleted_at IS NULL") {
				born := -1
				for j, p := range m.stmts {
					if strings.Contains(p, "ADD COLUMN IF NOT EXISTS deleted_at") {
						born = j
					}
				}
				ok := born >= 0 && born < i
				later := "在本文件里没出生（索引建在不存在的列上，迁移直接报错）"
				if born >= 0 {
					later = fmt.Sprintf("却要到第 %d 行才出生（索引排在列前面＝建在不存在的列上，迁移直接报错）", born+1)
				}
				say(fmt.Sprintf("   %s R5 软删列序：%s 第 %d 行的部分索引引用 deleted_at，该列%s", mk[ok], m.file, i+1,
					map[bool]string{true: fmt.Sprintf("在第 %d 行先出生", born+1), false: later}[ok]))
			}
		}
		// R6 恢复路径带 family_id
		for i, l := range m.stmts {
			if strings.Contains(l, "SET deleted_at = NULL") {
				say(fmt.Sprintf("   %s R6 恢复路径：%s 第 %d 行误删恢复 SQL %s", mk[strings.Contains(l, "family_id")], m.file, i+1,
					map[bool]string{true: "带 family_id 谓词（跨家庭误恢复＝泄露）", false: "只按 id 恢复——没有 family_id 就是跨家庭"}[strings.Contains(l, "family_id")]))
			}
		}
	}
	// R3 *_cents 三查：bigint / NOT NULL（同文件或后续收紧）/ 金额列不许 DEFAULT 0
	for _, m := range ms {
		for i, l := range m.stmts {
			if !strings.Contains(l, "_cents") || strings.HasPrefix(strings.TrimSpace(l), "--") {
				continue
			}
			for _, w := range strings.Fields(l) {
				name := strings.TrimRight(w, ",;(")
				if !strings.HasSuffix(name, "_cents") {
					continue
				}
				rest := l[strings.Index(l, name)+len(name):]
				f := strings.Fields(rest)
				if len(f) == 0 {
					continue
				}
				typ := strings.TrimRight(f[0], ",;()")
				if typ != "bigint" && typ != "integer" {
					continue // 不是列定义行（UPDATE/索引里也出现列名）
				}
				notnull := strings.Contains(rest, "NOT NULL") || containsLater(m.stmts, i, "ALTER COLUMN "+name+" SET NOT NULL")
				def0 := strings.Contains(rest, "DEFAULT 0")
				money := strings.HasPrefix(name, "amount_") || strings.HasPrefix(name, "balance_")
				okType, okNull, okDef := typ == "bigint", notnull, !(money && def0)
				say(fmt.Sprintf("   %s R3 分单位列：%s 第 %d 行 %s → 类型 %s%s、NOT NULL=%s、DEFAULT 0=%s%s",
					mk[okType && okNull && okDef], m.file, i+1, name, typ, map[bool]string{true: "", false: " ❌（分是整数，必须 bigint）"}[okType],
					map[bool]string{true: "是（含后续收紧）", false: "否 ❌"}[okNull], map[bool]string{true: "有", false: "无"}[def0],
					map[bool]string{true: " ❌（金额列 DEFAULT 0＝把没记的当零花，假成功）", false: ""}[money && def0]))
			}
		}
	}
	// R4 主索引续存：(family_id, occurred_at) WHERE deleted_at IS NULL 必须在「已跑+本次」的并集里
	need := "finance.finance_transaction (family_id, occurred_at) WHERE deleted_at IS NULL"
	say(fmt.Sprintf("   %s R4 报表主索引：(family_id, occurred_at) WHERE deleted_at IS NULL 在迁移并集里=%v——缺了它，S11 d14 那条 EXPLAIN 会退化成全表扫，必须补进真环境清单",
		mk[strings.Contains(allText, need)], strings.Contains(allText, need)))
	return bad
}

func badMigrations(which string) []mig {
	ms := safeMigrations()
	switch which {
	case "noBackfill": // 00009 把回填那行删掉
		for i := range ms {
			if ms[i].file == "00009_txn_amount_to_cents" {
				ms[i].stmts = []string{ms[i].stmts[0], ms[i].stmts[2], ms[i].stmts[3]}
			}
		}
	case "dropLedger": // 直接删 balance_cents
		ms = append(ms, mig{"00012_bad_drop_balance", []string{"ALTER TABLE finance.finance_account DROP COLUMN IF EXISTS balance_cents;"}, nil, true})
	case "intCents": // 分单位列写成 integer + DEFAULT 0
		ms = append(ms, mig{"00012_bad_cents_type", []string{"ALTER TABLE finance.finance_budget ADD COLUMN IF NOT EXISTS amount_cents integer NOT NULL DEFAULT 0;"}, nil, true})
	case "indexFirst": // 软删列序反了：索引在列出生前
		ms[3].stmts = []string{ms[3].stmts[2], ms[3].stmts[0], ms[3].stmts[1], ms[3].stmts[3], ms[3].stmts[4]}
	case "noFam": // 恢复 SQL 丢了 family_id
		ms[3].stmts[4] = "UPDATE homeos.homeos_notification SET deleted_at = NULL, deleted_by = NULL WHERE id = $1;"
	}
	return ms
}
func containsLater(ls []string, from int, sub string) bool { // NOT NULL 允许由后续语句收紧（先加可空列→回填→SET NOT NULL）
	for j := from + 1; j < len(ls); j++ {
		if strings.Contains(ls[j], sub) {
			return true
		}
	}
	return false
}

