func findIdx(lines []string, pred func(string) bool) []int {
	var r []int
	for i, l := range lines {
		if pred(l) {
			r = append(r, i+1)
		}
	}
	return r
}
func first(ix []int) int {
	if len(ix) == 0 {
		return 0
	}
	return ix[0]
}
func numsStr(ix []int) string {
	p := make([]string, len(ix))
	for i, x := range ix {
		p[i] = strconv.Itoa(x)
	}
	return strings.Join(p, "/")
}
func quoted(s string) string { // 第一个双引号段
	i := strings.Index(s, `"`)
	if i < 0 {
		return ""
	}
	j := strings.Index(s[i+1:], `"`)
	if j < 0 {
		return ""
	}
	return s[i+1 : i+1+j]
}

// —— 六条断言：只读上面文本，返回（是否绿，证据句）——

func a1(x arts) (bool, string) {
	var det []string
	ok := true
	for _, s := range []string{"finance", "calendar", "postgres", "nginx"} {
		start := first(findIdx(x.compose, func(l string) bool { return l == "  "+s+":" }))
		hc := 0
		for i := start; i < len(x.compose); i++ {
			l := x.compose[i]
			if l == "    healthcheck:" {
				hc = i + 1
				break
			}
			if len(l) > 2 && l[0] == ' ' && l[1] == ' ' && l[2] != ' ' { // 下一个 2 空格键＝出了本服务块
				break
			}
		}
		if hc == 0 {
			ok = false
		}
		det = append(det, fmt.Sprintf("%s:服务第%d行→healthcheck第%d行", s, start, hc))
	}
	return ok, "四服务均带 healthcheck：" + strings.Join(det, "；") + "（d05 的节拍 30s/3s/3/20s 全文统一）"
}

func a2(x arts) (bool, string) {
	var pub []int
	var ports []string
	for i, l := range x.compose {
		t := strings.TrimSpace(l)
		if !strings.HasPrefix(t, `- "`) {
			continue
		}
		q := quoted(t)
		if q == "" || !strings.Contains(q, ":") { // expose 的 "8080" 没有宿主段
			continue
		}
		pub = append(pub, i+1)
		ports = append(ports, q)
	}
	set := map[string]bool{}
	for _, p := range ports {
		set[strings.Split(p, ":")[0]] = true
	}
	ok := len(set) == 2 && set["80"] && set["443"]
	return ok, fmt.Sprintf("宿主发布={%s}（行 %s）；期望恰为 {80,443}——5432/8080/8081 只许走 homecube-net 内网", jset(set), numsStr(pub))
}
func jset(m map[string]bool) string {
	var k []string
	for x := range m {
		k = append(k, x)
	}
	sort.Strings(k)
	return strings.Join(k, ",")
}

func urlPath(l string) string { // 行内 http://host[:port]/PATH → /PATH
	i := strings.Index(l, "http://")
	if i < 0 {
		return ""
	}
	rest := l[i+len("http://"):]
	if j := strings.IndexByte(rest, '"'); j >= 0 {
		rest = rest[:j]
	}
	if k := strings.Index(rest, "/"); k >= 0 {
		return rest[k:]
	}
	return "/"
}

type ref struct {
	src  string
	line int
	path string
}

func a3(x arts) (bool, string) {
	var refs []ref
	for i, l := range x.compose {
		if strings.Contains(l, "test:") && strings.Contains(l, "http://localhost") {
			refs = append(refs, ref{"compose", i + 1, urlPath(l)})
		}
	}
	for i, l := range x.nginx {
		f := strings.Fields(l)
		if len(f) >= 3 && f[0] == "location" && f[1] == "=" {
			refs = append(refs, ref{"nginx", i + 1, f[2]})
		}
	}
	uniq := map[string]bool{}
	var det []string
	for _, r := range refs {
		uniq[r.path] = true
		det = append(det, fmt.Sprintf("%s第%d行=%s", r.src, r.line, r.path))
	}
	ok := len(refs) >= 2 && len(uniq) == 1 && uniq["/healthz"]
	return ok, fmt.Sprintf("健康路径引用 %d 处（%s）；跨文本一致=/healthz? %v", len(refs), strings.Join(det, "，"), ok)
}

func a4(x arts) (bool, string) {
	seen := map[int]map[string]bool{}
	for _, l := range x.miglist {
		f := strings.Fields(l)
		if len(f) == 0 || !strings.HasSuffix(f[0], ".sql") || len(f[0]) < 9 {
			continue
		}
		n, err := strconv.Atoi(f[0][:5]) // 五位数迁移号（00001..）
		if err != nil {
			continue
		}
		if seen[n] == nil {
			seen[n] = map[string]bool{}
		}
		if strings.HasSuffix(f[0], "_up.sql") {
			seen[n]["up"] = true
		} else {
			seen[n]["down"] = true
		}
	}
	var nums []int
	for n := range seen {
		nums = append(nums, n)
	}
	sort.Ints(nums)
	issues := 0
	for i, n := range nums {
		if n != i+1 || !seen[n]["up"] || !seen[n]["down"] {
			issues++
		}
	}
	ok := issues == 0 && len(nums) > 0
	top := nums[len(nums)-1]
	return ok, fmt.Sprintf("迁移 %d 个号（%05d..%05d）：连号无缺口且 up/down 成对=%v；当前版本号=最高号 %05d——真机断言 schema_migrations 里查得到它",
		len(nums), nums[0], top, ok, top)
}

func svcOf(l string) string {
	i := strings.Index(l, `"svc":"`)
	if i < 0 {
		return ""
	}
	return quoted(l[i+6:])
}

func a5(x arts) (bool, string) {
	biz := map[string]bool{"finance": true, "calendar": true, "homeos": true}
	var n, miss []int
	for i, l := range x.logs {
		s := svcOf(l)
		if s == "" {
			continue
		}
		if biz[s] {
			n = append(n, i+1)
			if !strings.Contains(l, `"family_id":"`) {
				miss = append(miss, i+1)
			}
		}
	}
	clean := 0
	for _, l := range append(append([]string{}, x.logs...), x.compose...) {
		if strings.Contains(strings.ToLower(l), "password=") || strings.Contains(l, "PLAINTEXT") {
			clean++
		}
	}
	ok := len(miss) == 0 && clean == 0 && len(n) == len(biz)
	return ok, fmt.Sprintf("业务日志 %d 行（行 %s）全带 family_id（缺=%v）、compose+日志明文口令命中 %d 处（口令只走 ${VAR:?}/secrets，日志只走字段白名单）",
		len(n), numsStr(n), miss, clean)
}

func a6(x arts) (bool, string) {
	var det []string
	bad := 0
	for i, l := range x.compose {
		if !strings.HasPrefix(l, "    image: ") {
			continue
		}
		img := strings.TrimPrefix(l, "    image: ")
		at := strings.LastIndex(img, "/")
		colon := strings.Index(img[at+1:], ":")
		tag := ""
		if colon >= 0 {
			tag = img[at+1+colon+1:]
		}
		v := tag != "" && tag != "latest"
		if !v {
			bad++
		}
		det = append(det, fmt.Sprintf("第%d行 %s（%s）", i+1, img, map[bool]string{true: "钉死", false: "未钉死＝干净机器碰运气"}[v]))
	}
	return bad == 0, strings.Join(det, "；")
}

