type st struct {
	id                         int
	name, method, path, status string
	crid                       bool
	win                        string
	line                       int
}

func parse(ls []string) ([]st, string, int64) {
	var ss []st
	topWin := ""
	var sum int64
	cur := -1
	for i, raw := range ls {
		t := strings.TrimSpace(raw)
		switch {
		case strings.HasPrefix(t, "window:"):
			v := strings.TrimPrefix(t, "window:")
			v = strings.TrimSpace(strings.Split(v, "#")[0])
			topWin = strings.Trim(v, `"`)
		case strings.HasPrefix(t, "fixture_amounts_cents:"):
			v := strings.SplitN(t, ":", 2)[1]
			v = strings.TrimSpace(strings.Split(v, "#")[0])
			v = strings.Trim(v, "[]")
			for _, p := range strings.Split(v, ",") {
				n, err := strconv.ParseInt(strings.TrimSpace(p), 10, 64)
				if err == nil {
					sum += n
				}
			}
		case strings.HasPrefix(t, "- id:"):
			n, _ := strconv.Atoi(strings.TrimSpace(strings.SplitN(t, ":", 2)[1]))
			ss = append(ss, st{id: n, line: i + 1})
			cur = len(ss) - 1
		case cur >= 0 && strings.HasPrefix(t, "name:"):
			ss[cur].name = strings.TrimSpace(strings.SplitN(t, ":", 2)[1])
		case cur >= 0 && strings.HasPrefix(t, "method:"):
			ss[cur].method = strings.TrimSpace(strings.SplitN(t, ":", 2)[1])
		case cur >= 0 && strings.HasPrefix(t, "path:"):
			p := strings.TrimSpace(strings.SplitN(t, ":", 2)[1])
			ss[cur].path = p
			if j := strings.Index(p, "window="); j >= 0 {
				ss[cur].win = strings.TrimSuffix(p[j+len("window="):], "/")
			}
		case cur >= 0 && strings.HasPrefix(t, "body_keys:"):
			ss[cur].crid = strings.Contains(t, "client_request_id")
		case cur >= 0 && strings.HasPrefix(t, "expect_status:"):
			ss[cur].status = strings.TrimSpace(strings.SplitN(t, ":", 2)[1])
		}
	}
	return ss, topWin, sum
}

func numAfter(line, marker string) (int64, bool) {
	i := strings.Index(line, marker)
	if i < 0 {
		return 0, false
	}
	rest := line[i+len(marker):]
	dig := 0
	for _, c := range rest {
		if c < '0' || c > '9' {
			break
		}
		dig++
	}
	if dig == 0 {
		return 0, false
	}
	n, err := strconv.ParseInt(rest[:dig], 10, 64)
	return n, err == nil
}

func hasDecimalYuan(l string) bool { // 「数字.数字 … 元」
	if !strings.Contains(l, "元") {
		return false
	}
	for i := 0; i+2 < len(l); i++ {
		if l[i] >= '0' && l[i] <= '9' && l[i+1] == '.' && l[i+2] >= '0' && l[i+2] <= '9' {
			return true
		}
	}
	return false
}

// expectOf：取第 id 步的 expect 行原文（检查读文本，不读内存里的构造值）
func expectOf(ls []string, id int) string {
	cur := 0
	for _, raw := range ls {
		t := strings.TrimSpace(raw)
		if strings.HasPrefix(t, "- id:") {
			cur, _ = strconv.Atoi(strings.TrimSpace(strings.SplitN(t, ":", 2)[1]))
		}
		if cur == id && strings.HasPrefix(t, `expect: "`) {
			return t
		}
	}
	return ""
}

func audit(ls []string, brief bool) int {
	bad := 0
	say := func(s string) {
		bad += strings.Count(s, "❌")
		if !brief || strings.Contains(s, "❌") {
			fmt.Println(s)
		}
	}
	ss, topWin, fixtureSum := parse(ls)

	// C1 七步齐全有序、四要素不缺
	miss := 0
	for i, s := range ss {
		if s.id != i+1 || s.method == "" || s.path == "" || s.status == "" {
			miss++
		}
	}
	ok := len(ss) == 7 && miss == 0
	say(fmt.Sprintf("   %s C1 结构：steps=%d 个、id 连号 1..7、method/path/expect_status 齐=%v", mk[ok], len(ss), ok))

	// C2 前缀属于 d07 注册表（? 之前算路径）
	var badP []string
	for _, s := range ss {
		p := s.path
		if j := strings.Index(p, "?"); j >= 0 {
			p = p[:j]
		}
		in := false
		for _, pf := range prefixes {
			if strings.HasPrefix(p, pf) {
				in = true
			}
		}
		if !in {
			badP = append(badP, fmt.Sprintf("步%d %s（第%d行）", s.id, s.path, s.line))
		}
	}
	say(fmt.Sprintf("   %s C2 前缀：七条 path 全部落在注册表 %v 内；越界=%v", mk[len(badP) == 0], prefixes, badP))

	// C3 状态码与方法匹配：POST 新建=201，GET=200；非法码（4xx 当预期）也算错
	var badS []string
	for _, s := range ss {
		want := map[string]string{"POST": "201", "GET": "200"}[s.method]
		if s.status != want {
			badS = append(badS, fmt.Sprintf("步%d %s→%s（应为 %s）", s.id, s.method, s.status, want))
		}
	}
	say(fmt.Sprintf("   %s C3 状态码：与方法的映射全对=%v；错配=%v", mk[len(badS) == 0], len(badS) == 0, badS))

	// C4 每个写请求带 client_request_id（幂等红线）
	var noCrid []string
	for _, s := range ss {
		if s.method == "POST" && !s.crid {
			noCrid = append(noCrid, fmt.Sprintf("步%d %s", s.id, s.name))
		}
	}
	say(fmt.Sprintf("   %s C4 幂等键：POST 步全带 client_request_id=%v；漏网=%v", mk[len(noCrid) == 0], len(noCrid) == 0, noCrid))

	// C5 金额算术自洽：fixture 现场求和，步 6/7 的期望必须等于它；行数=笔数；全文无「小数+元」
	n6, ok6 := numAfter(expectOf(ls, 6), mkTotal)
	nR, okR := numAfter(expectOf(ls, 7), mkRows)
	nS, okS := numAfter(expectOf(ls, 7), mkSum)
	decLine := 0
	for i, raw := range ls {
		if hasDecimalYuan(raw) {
			decLine = i + 1
		}
	}
	ok5 := ok6 && okR && okS && n6 == fixtureSum && nR == int64(len(fixture)) && nS == fixtureSum && decLine == 0
	say(fmt.Sprintf("   %s C5 算术：Σfixture=%d（现场加）→ 步6 期望=%d、步7 行数=%d/和=%d、小数+元出现在第%d行（0=没有）",
		mk[ok5], fixtureSum, n6, nR, nS, decLine))

	// C6 窗口单源：path 里的 window= 必须等于顶层 window
	var drift []string
	for _, s := range ss {
		if s.win != "" && s.win != topWin {
			drift = append(drift, fmt.Sprintf("步%d=%s", s.id, s.win))
		}
	}
	say(fmt.Sprintf("   %s C6 窗口：顶层=%s；漂移=%v（跨窗比较＝红线的部署版）", mk[len(drift) == 0], topWin, drift))
	return bad
}

func inj(which string) []string {
	b := map[string]string{}
	switch which {
	case "prefix":
		b["p3"] = "/api/lab/accounts"
	case "crid":
		b["nocrid"] = "1"
	case "decimal":
		b["dec"] = "1"
	case "window":
		b["xwin"] = "2026-09"
	}
	return smokeYAML(b)
}

