// W59 d14：冒烟脚本 —— 顺序、失败即停、可重复执行不产生脏数据
//
// d13 把七步各断言什么定了下来，今天要落成一份真能跑的 bash + curl 脚本。难点不在 curl，在两件事：
// 一是「任一步失败必须当场停并把响应体吐出来」——否则第 3 步 502、第 4 步照样发，你看到七步全红的
// 假象，真坏的那层反而被淹在噪音里；二是「重复跑不许堆脏数据」——冒烟脚本天天跑，若每跑一次多五笔
// 流水，第 6 步的月总额断言就永远追不上自己刚写进去的数据。解法是 crid 钉死成固定字面量：
// 二跑全部命中幂等，行数增量必须为 0。
// 本机没有 nginx、没有 PG、Docker 守护进程没起，所以脚本不真发 HTTP：程序先生成脚本文本并做静态
// 检查，再用内存假服务把 step 声明逐行「演」两遍（含二跑增量对账），两个反例也当场演出来。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d14
package main

import (
	"fmt"
	"sort"
	"strings"
)

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }

// scriptText 生成冒烟脚本（学员侧路径 homecube/deploy/smoke/smoke.sh）。
// cridMode="volatile" 是反例开关：crid 掺进 $(date +%s)，每次跑都是新幂等键。
func scriptText(cridMode string) string {
	crid := `crid() { printf 'smoke-%s-%s' "$1" "$2"; }   # 固定字面量：与时间、随机数无关`
	if cridMode == "volatile" {
		crid = `crid() { printf 'smoke-%s-%s-%s' "$1" "$2" "$(date +%s)"; }  # 反例：每次跑都不同`
	}
	return `#!/usr/bin/env bash
# homecube/deploy/smoke/smoke.sh —— S14 冒烟七步：失败即停、重复执行不产生脏数据
set -euo pipefail
BASE=${BASE:-http://homecube.local}
fail() { echo "❌ 步 $1 失败：HTTP $2" >&2; printf '%s\n' "$3" | sed 's/^/    响应体| /' >&2; exit 1; }
post() { local code body; body=$(curl -sS -X POST -H 'Content-Type: application/json' -H "X-Client-Request-Id: $2" -d "$3" "$BASE$1");
  code=$(echo "$body" | jq -r '.status_code // 201'); [[ "$code" == "$4" ]] || fail "$1" "$code" "$body"; echo "$body"; }
get()  { local body; body=$(curl -sS "$BASE$1"); echo "$body" | jq -e ".$2" >/dev/null || fail "$1" "200" "$body"; echo "$body"; }
` + crid + `
# —— 七步声明（步号即执行顺序，驱动逐行解析本表，不许并行乱序）——
step 1 注册       POST /api/homeos/v1/register        201 member_id        delta=member+1
step 2 建家庭     POST /api/homeos/v1/families        201 family_id        delta=family+1
step 3 建账户     POST /api/finance/v1/accounts       201 account_id       delta=account+1
step 4 记五笔     POST /api/finance/v1/transactions   201 txn_id           repeat=5 delta=txn+5
step 5 到期中心   GET  /api/calendar/v1/due           200 due_item         delta=0
step 6 看统计     GET  /api/finance/v1/summary        200 month_total_cents delta=0
step 7 导出       GET  /api/finance/v1/export         200 csv_rows=5       delta=0
run_steps() { while read -r _ idx name method path want field spec rest; do
    [[ "$idx" =~ ^[0-9]+$ ]] || continue
    reps=1; case "$spec" in repeat=*) reps=${spec#repeat=};; esac
    for i in $(seq 1 "$reps"); do
      if [ "$method" = POST ]; then post "$path" "$(crid "$idx" "$i")" "{}" "$want"; else get "$path" "${field%%=*}"; fi
    done; done < <(grep '^step ' "$0"); }
run_steps
echo "✔ 冒烟七步全过（重复跑命中幂等，行数增量为 0）"`
}

type stepDef struct {
	idx    int
	name   string
	method string
	path   string
	want   int
	field  string
	repeat int
	delta  map[string]int
}

// parseSteps 真从脚本文本里解析 step 行——解析不动，脚本就等于废（与 bash 驱动读同一张表）。
func parseSteps(text string) ([]stepDef, []string) {
	var out []stepDef
	var errs []string
	for i, ln := range strings.Split(text, "\n") {
		if !strings.HasPrefix(ln, "step ") {
			continue
		}
		f := strings.Fields(ln)
		if len(f) < 7 {
			errs = append(errs, fmt.Sprintf("第 %d 行 step 字段不足", i+1))
			continue
		}
		st := stepDef{name: f[2], method: f[3], path: f[4], field: f[6], repeat: 1, delta: map[string]int{}}
		fmt.Sscanf(f[1], "%d", &st.idx)
		fmt.Sscanf(f[5], "%d", &st.want)
		for _, k := range f[7:] {
			if strings.HasPrefix(k, "repeat=") {
				fmt.Sscanf(k, "repeat=%d", &st.repeat)
			}
			if strings.HasPrefix(k, "delta=") && k != "delta=0" {
				spec := strings.TrimPrefix(k, "delta=")
				if j := strings.LastIndexAny(spec, "+"); j >= 0 {
					var v int
					fmt.Sscanf(spec[j+1:], "%d", &v)
					st.delta[spec[:j]] = v
				}
			}
		}
		if st.repeat < 1 {
			st.repeat = 1
		}
		out = append(out, st)
	}
	return out, errs
}

// ---- 内存假服务：只实现脚本会打到的路由，行数增量由它的表计数当场算 ----
type fake struct {
	rows    map[string]int // member/family/account/txn 行数
	seen    map[string]int // crid -> 已受理（幂等表）
	dirty   bool           // volatile crid：二跑的键与首跑不同，幂等认不出来
	breakAt int            // >0 时该 finance 步直接 502，演「失败即停」
}

func newFake() *fake { return &fake{rows: map[string]int{}, seen: map[string]int{}} }

func (f *fake) call(s stepDef, run, i int) (int, string, map[string]int) {
	d := map[string]int{}
	if f.breakAt == s.idx && s.method == "POST" && strings.Contains(s.path, "finance") {
		return 502, `{"code":50200,"message":"upstream connect error: finance"}`, d
	}
	if s.method == "GET" && f.rows["txn"] == 0 && (strings.Contains(s.path, "due") || strings.Contains(s.path, "export")) {
		return 422, `{"code":42201,"message":"前置数据缺失：txn=0（第 4 步没跑成？）"}`, d
	}
	crid := fmt.Sprintf("smoke-%d-%d", s.idx, i)
	if f.dirty {
		crid = fmt.Sprintf("%s-r%d", crid, run)
	}
	if s.method == "POST" {
		if f.seen[crid] > 0 {
			return 200, fmt.Sprintf(`{"idempotent_hit":true,"crid":"%s"}`, crid), d
		}
		f.seen[crid]++
		for k, v := range s.delta {
			per := v / s.repeat // delta= 声明的是整步合计：repeat=5 时每发只插 1 行
			f.rows[k] += per
			d[k] = per
		}
		return s.want, fmt.Sprintf(`{"%s":"ok"}`, s.field), d
	}
	body := strings.SplitN(s.field, "=", 2)[0]
	if strings.HasPrefix(s.field, "csv_rows") {
		body = fmt.Sprintf("csv_rows=%d", f.rows["txn"])
	}
	return s.want, fmt.Sprintf(`{"%s":"ok"}`, body), d
}

func drow(d map[string]int) string {
	if len(d) == 0 {
		return "0（只读/命中幂等）"
	}
	var ks []string
	for k := range d {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	parts := make([]string, 0, len(ks))
	for _, k := range ks {
		parts = append(parts, fmt.Sprintf("%s+%d", k, d[k]))
	}
	return strings.Join(parts, ",")
}

// runScript 按解析出的步序演脚本；返回行数增量合计。打印的是假服务实测增量，不是声明值。
func runScript(f *fake, steps []stepDef, run int) map[string]int {
	tot := map[string]int{}
	for i, s := range steps {
		measured := map[string]int{}
		for r := 0; r < s.repeat; r++ {
			code, body, d := f.call(s, run, r+1)
			if code != s.want && code != 200 {
				fmt.Printf("    ❌ 第 %d 步「%s」第 %d 发：HTTP %d，响应体 %s\n", s.idx, s.name, r+1, code, body)
				fmt.Printf("       set -euo pipefail + fail() 当场 exit 1：后面 %d 步一条都没发出去 ← 这就是「失败即停」\n", len(steps)-i-1)
				return tot
			}
			for k, v := range d {
				measured[k] += v
			}
		}
		fmt.Printf("    第 %d 步 %-5s %-4s %-32s HTTP %d %-16s 实测行数增量 %s\n",
			s.idx, s.name, s.method, s.path, s.want, s.field, drow(measured))
		for k, v := range measured {
			tot[k] += v
		}
	}
	return tot
}

func sum(m map[string]int) int {
	t := 0
	for _, v := range m {
		t += v
	}
	return t
}

func lint(text string) int { // 静态检查：「停」与「可重复」的骨架在发第一发 curl 之前就该看出来
	bad := 0
	chk := func(ok bool, name, ev string) {
		if !ok {
			bad++
		}
		fmt.Printf("  %s %-22s %s\n", mk[ok], name, ev)
	}
	chk(strings.Contains(text, "set -euo pipefail"), "失败即停骨架", "set -e 遇非零退出即停，pipefail 让管道里 curl 的失败不被 tail/jq 吞掉")
	chk(strings.Contains(text, "fail()") && strings.Contains(text, "exit 1") && strings.Contains(text, ">&2"), "失败要吐出响应体", "fail() 打 HTTP 码并把响应体送 stderr——只报「失败了」的脚本没法定位哪层坏了")
	var dynHits []string
	for i, ln := range strings.Split(text, "\n") {
		if strings.Contains(ln, "smoke-") && (strings.Contains(ln, "$(date") || strings.Contains(ln, "$RANDOM")) {
			dynHits = append(dynHits, fmt.Sprintf("第 %d 行", i+1))
		}
	}
	chk(len(dynHits) == 0, "crid 只用固定字面量", map[bool]string{
		true:  "幂等的前提：同一个 crid 服务端才认得出「这是同一请求」",
		false: "命中 " + strings.Join(dynHits, "、") + " —— 掺了时间戳/随机数，重复跑就是插脏数据",
	}[len(dynHits) == 0])
	steps, perr := parseSteps(text)
	chk(len(steps) == 7 && len(perr) == 0, "七步声明可解析", fmt.Sprintf("解析出 %d 步、字段错误 %d 处；bash 驱动与本程序读同一张表", len(steps), len(perr)))
	postOK := true
	for _, st := range steps {
		if st.method == "POST" && len(st.delta) == 0 {
			postOK = false
		}
	}
	chk(postOK, "写步都申报行数增量", "delta= 写进步声明，二跑增量为 0 才有东西可对账")
	slash := string('/') // 检测串现场拼装：源码与 stdout 都不出现任何本机绝对路径字面量
	chk(!strings.Contains(text, slash+"tmp"+slash) && !strings.Contains(text, slash+"Users"+slash), "产物只有学员侧路径", "脚本只写 BASE 与 /api/{code}/ 前缀，无本机绝对路径")
	return bad
}

