// W59 d15：三系统协作的观测 —— 一条 request_id 走全程
//
// S12 讲过协作契约：finance / calendar 发事件，homeos 落通知（未读 +1、动态流 +1）。但「协作对了」
// 在真故障时只有一个证据：同一条 request_id 能在三个服务的日志里都 grep 到，串起来就是完整因果链。
// 串不上会是什么样？用户说「我记了一笔带还款日的账，到期中心没有」——你只能三个服务挨个翻日志，
// 靠时间戳肉眼对齐，跨服务时钟差 200ms 就把结论带偏。所以追踪字段必须进事件信封，而不是只进 HTTP 头。
// 本机没有 Docker/nginx/PG，也不起真 HTTP：程序生成三份日志文本（同一条 req-7f3a 贯穿），
// 现场 grep 证明三个服务都命中；再用带幂等表的假消费者把「正常 / 事件丢失 / 事件重复」三种时序各自
// 的未读数当场算出来——重复投递的拦截数、丢失后的缺口都是本程序的返回值，不是手写的答案。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d15
package main

import (
	"fmt"
	"sort"
	"strings"
)

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }

// 同一条请求：用户 POST 一笔带 due_at 的流水（crid pay-0001），事件链 finance → calendar → homeos。
// 追踪三键恒在：family_id 恒进每条日志（红线）、request_id 跨服务串链、写操作带 client_request_id。
var logs = map[string][]string{}
var logOrder = []string{"finance", "calendar", "homeos"}

func buildLogs() {
	rid, fid := "req-7f3a", "fam-a"
	w := func(svc, ts, msg string, kv map[string]string) {
		ln := fmt.Sprintf(`{"ts":"%s","svc":"%s","family_id":"%s","request_id":"%s"`, ts, svc, fid, rid)
		var ks []string
		for k := range kv {
			ks = append(ks, k)
		}
		sort.Strings(ks)
		for _, k := range ks {
			ln += fmt.Sprintf(`,"%s":%s`, k, kv[k])
		}
		logs[svc] = append(logs[svc], ln+`,"msg":"`+msg+`"}`)
	}
	w("finance", "09:00:00.101", "POST /api/finance/v1/transactions 201",
		map[string]string{"crid": `"pay-0001"`, "route": `"/v1/transactions"`})
	w("finance", "09:00:00.118", "INSERT finance_transaction（含 due_at）",
		map[string]string{"crid": `"pay-0001"`, "txn_id": `"txn-9007"`})
	w("finance", "09:00:00.119", "INSERT finance_outbox finance.due.registered（同一事务）",
		map[string]string{"crid": `"pay-0001"`, "kind": `"reminder"`})
	w("finance", "09:00:00.140", "outbox 发布 finance.due.registered，信封带追踪三键",
		map[string]string{"event": `"finance.due.registered"`})
	w("calendar", "09:00:00.212", "消费 finance.due.registered",
		map[string]string{"event": `"finance.due.registered"`, "dedup_hit": "false"})
	w("calendar", "09:00:00.219", "UPSERT calendar_due + 发 due.soon",
		map[string]string{"crid": `"pay-0001"`, "due_id": `"due-3301"`})
	w("homeos", "09:00:00.305", "消费 due.soon：写 homeos_notification、homeos_activity",
		map[string]string{"event": `"calendar.due.soon"`, "dedup_hit": "false"})
	w("homeos", "09:00:00.306", "未读聚合刷新：unread=1（服务端一处，动态只由事件总线写入）",
