func grepSvc(rid string) (int, []string) { // 现场 grep：命中行号逐份列出，链断在哪一段一眼可见
	var ev []string
	total := 0
	for _, svc := range logOrder {
		hits := []string{}
		for i, ln := range logs[svc] {
			if strings.Contains(ln, rid) {
				hits = append(hits, fmt.Sprintf("%s 第 %d 行", svc, i+1))
			}
		}
		total += len(hits)
		ev = append(ev, fmt.Sprintf("%s 命中 %d/%d 行（%s）", svc, len(hits), len(logs[svc]), strings.Join(hits, "、")))
	}
	return total, ev
}

// ---- 假消费者：homeos 侧幂等键 (source_system, source_id, kind)，与 S10 d32 / S12 契约同源 ----
type consumer struct {
	seen     map[string]bool
	unread   int
	feed     int
	blocked  int // 被幂等表挡掉的重复投递数（当场算出来的，不是叙述）
	useDedup bool
}

func newConsumer(useDedup bool) *consumer {
	return &consumer{seen: map[string]bool{}, useDedup: useDedup}
}

func (c *consumer) deliver(src, id, kind string) {
	key := src + "|" + id + "|" + kind
	if c.useDedup {
		if c.seen[key] {
			c.blocked++
			return
		}
		c.seen[key] = true
	}
	c.unread++ // 通知行 +1 → 未读 +1
	c.feed++   // 动态流只由事件总线写这一处
}

func main() {
