// W59 d16：端到端一致性对账 —— 四个数必须同值
//
// 冒烟第七步跑通了不代表系统「对」：记的 5 笔、报表月桶总额、导出 CSV 的数据行数、home/summary 的
// 数字，是四条独立代码路径读同一份事实。S11 定过稠密桶契约（空桶照出行、一行 = 一个桶），S12 定过
// 聚合服务端只有一处——收口日就要把四个口径并排放，任何一个不同值都说明有一处路径没走同一份契约。
// 今天现场造一种最阴的漂移：导出把日界算在 UTC 而不是家庭时区。亚洲时区早上 6 点前的账会掉进
// 上个月，行数还可能侥幸相同（错两笔进又错两笔出），金额一定不同——所以跨窗比较必须被程序拒绝，
// 行数与金额要成对对账。全部计算在本机内存里做：5 笔流水用钉死的日期、金额一律 *_cents 整数、
// 时区用 time.FixedZone 显式建模（不用宿主时区，两次跑字节才会一致），真库对账留给真环境复跑。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d16
package main

import (
	"fmt"
	"strings"
	"time"
)

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }

// ---- 钉死的数据：5 笔流水（S10 语义：一笔一行，金额 cents 整数）----
type txn struct {
	id       string
	amt      int64 // *_cents，红线：全程整数分，不许浮点
	occurred time.Time
	fam      string
}

var cst = time.FixedZone("Asia/Shanghai", 8*3600) // 家庭时区从配置来（HOMEUBE_TIMEZONE），这里显式建模

var txns = []txn{
	{"txn-9001", 3250, time.Date(2026, 11, 3, 18, 40, 0, 0, cst), "fam-a"},
	{"txn-9002", 120000, time.Date(2026, 11, 7, 9, 15, 0, 0, cst), "fam-a"},
	{"txn-9003", 1500, time.Date(2026, 11, 12, 7, 2, 0, 0, cst), "fam-a"},
	{"txn-9004", 8800, time.Date(2026, 11, 1, 6, 5, 0, 0, cst), "fam-a"}, // 边界笔：CST 是 11 月，UTC 还是 10 月 31 日 22:05
	{"txn-9005", 4990, time.Date(2026, 11, 20, 21, 33, 0, 0, cst), "fam-a"},
}

var window = "2026-11"

// bucketOf：按「口径时区」取年月——日界从哪来，桶就归哪个月。tz=nil 即 UTC 口径（反例）。
func bucketOf(t time.Time, tz *time.Location) string {
	if tz != nil {
		t = t.In(tz)
	} else {
		t = t.UTC()
	}
	return fmt.Sprintf("%04d-%02d", int(t.Year()), int(t.Month()))
}

type bucket struct {
	month string
	rows  int
	cents int64
}

// 稠密桶契约（S11 d07）：窗口清单给定后，空桶照出行、一行 = 一个桶，不许 compact。
func denseBuckets(tz *time.Location, months []string) []bucket {
	out := []bucket{}
	idx := map[string]int{}
	for _, m := range months {
		idx[m] = len(out)
		out = append(out, bucket{month: m})
	}
	for _, t := range txns {
		if t.fam != "fam-a" {
			continue
		}
		if i, ok := idx[bucketOf(t.occurred, tz)]; ok {
			out[i].rows++
			out[i].cents += t.amt
		}
	}
	return out
}

func csvText(tz *time.Location) []string { // 导出：数据行 = 窗口内笔数；反例传 nil（UTC 日界）
	lines := []string{"txn_id,occurred_at,amount_cents"}
	for _, t := range txns {
		if bucketOf(t.occurred, tz) == window {
			ts := t.occurred.In(map[bool]*time.Location{true: cst, false: time.UTC}[tz != nil])
			lines = append(lines, fmt.Sprintf("%s,%s,%d", t.id, ts.Format("2006-01-02T15:04:05Z07:00"), t.amt))
		}
	}
	return lines
}

type caliber struct { // 四个口径各自独立算出（rows,cents），并排靠 reconcile 对账
	name  string
	rows  int
	cents int64
	win   string
}

func reconcile(a, b caliber) string { // 跨窗比较必须被拒——不同窗口的两个数放在一起毫无意义
	if a.win != b.win {
		return fmt.Sprintf("拒绝比较：%s 窗 %s vs %s 窗 %s（口径未对齐，先统一窗口）", a.name, a.win, b.name, b.win)
	}
	if a.rows == b.rows && a.cents == b.cents {
		return fmt.Sprintf("同值：rows %d==%d、cents %d==%d", a.rows, b.rows, a.cents, b.cents)
	}
	dr := []string{}
	if a.rows != b.rows {
		dr = append(dr, fmt.Sprintf("行数差 %+d", b.rows-a.rows))
	}
	if a.cents != b.cents {
		dr = append(dr, fmt.Sprintf("金额差 %+d cents", b.cents-a.cents))
	}
	return "不同值：" + strings.Join(dr, "、")
}

func main() {
	sec(1, "事实源：5 笔流水（家庭 fam-a，窗口 "+window+"，时区从配置 HOMEUBE_TIMEZONE=Asia/Shanghai 建模）")
	for _, t := range txns {
		fmt.Printf("  %s  %+8d cents  CST=%s  UTC=%s  归属桶 CST=%s / UTC=%s\n", t.id, t.amt,
			t.occurred.In(cst).Format("2006-01-02 15:04"), t.occurred.UTC().Format("2006-01-02 15:04"),
			bucketOf(t.occurred, cst), bucketOf(t.occurred, nil))
	}

	sec(2, "四个口径各算各的（记的笔数 / 报表月桶 / 导出 CSV / home/summary），全部现算")
	// ① 记账侧：写进 finance_transaction 的窗口行数与金额
	c1 := caliber{"记账侧", 0, 0, window}
	for _, t := range txns {
		if bucketOf(t.occurred, cst) == window {
			c1.rows++
			c1.cents += t.amt
		}
	}
	// ② 报表侧：稠密月桶（2026-09..11 三个桶，空桶照出行）
	bs := denseBuckets(cst, []string{"2026-09", "2026-10", "2026-11"})
	fmt.Println("  报表月桶（稠密契约：一行 = 一个桶，空桶照出）：")
	for _, b := range bs {
		fmt.Printf("    %s  rows=%d  cents=%d%s\n", b.month, b.rows, b.cents,
			map[bool]string{true: "  ← 空桶仍出行", false: ""}[b.rows == 0])
	}
	contractOK := len(bs) == 3 && func() bool { // 桶月份必须恰等于给定窗口清单且单调
		for i, b := range bs {
			if b.month != []string{"2026-09", "2026-10", "2026-11"}[i] {
				return false
			}
		}
		return true
	}()
	nov := bs[2]
	c2 := caliber{"报表月桶", nov.rows, nov.cents, window}
	// ③ 导出侧：从生成的 CSV 文本里数行数、加金额列（对的是产物文本，不是内存变量）
	csv := csvText(cst)
	c3 := caliber{"导出 CSV", 0, 0, window}
	for i, ln := range csv {
		if i == 0 {
			continue
		}
		f := strings.Split(ln, ",")
		var cents int64
		fmt.Sscanf(f[2], "%d", &cents)
		c3.rows++
		c3.cents += cents
	}
	// ④ home/summary：服务端聚合一处（S12 契约），直接引用 ② 的同一函数返回值，不另写 SQL
	c4 := caliber{"home/summary", nov.rows, nov.cents, window}

	fmt.Println("  并排对账：")
	fmt.Printf("    %-12s rows=%d  cents=%d\n", c1.name, c1.rows, c1.cents)
	fmt.Printf("    %-12s rows=%d  cents=%d\n", c2.name, c2.rows, c2.cents)
	fmt.Printf("    %-12s rows=%d  cents=%d（数据行从 CSV 文本逐行数出，表头不计）\n", c3.name, c3.rows, c3.cents)
	fmt.Printf("    %-12s rows=%d  cents=%d（与报表同源：同一函数返回，不存在第二条聚合路径）\n", c4.name, c4.rows, c4.cents)
	allSame := c1.rows == c2.rows && c2.rows == c3.rows && c3.rows == c4.rows && c1.cents == c2.cents && c2.cents == c3.cents && c3.cents == c4.cents
	fmt.Printf("  %s 四口径同值：%s\n", mk[allSame && contractOK], reconcile(c1, c3))

	sec(3, "跨窗比较必须被拒（拿 10 月空桶去对 11 月导出，程序直接拒绝）")
	oct := bs[1]
	fmt.Printf("  %s\n", map[bool]string{true: "✅", false: "❌"}[strings.Contains(reconcile(caliber{"报表月桶", oct.rows, oct.cents, "2026-10"}, c3), "拒绝比较")]+
		" "+reconcile(caliber{"报表月桶", oct.rows, oct.cents, "2026-10"}, c3))

	sec(4, "现场造一种漂移：导出用了 UTC 日界（家庭时区契约被打破）")
	bad := csvText(nil)
	c5 := caliber{"导出 CSV(UTC 日界)", 0, 0, window}
	for i, ln := range bad {
		if i == 0 {
			continue
		}
		f := strings.Split(ln, ",")
		var cents int64
		fmt.Sscanf(f[2], "%d", &cents)
		c5.rows++
		c5.cents += cents
	}
	fmt.Printf("  漂移版 CSV 数据行 %d 行、金额 %d cents：%s\n", c5.rows, c5.cents, reconcile(c1, c5))
	for _, t := range txns {
		if bucketOf(t.occurred, cst) != bucketOf(t.occurred, nil) {
			fmt.Printf("  差在哪一笔当场点名：%s %+d cents：CST %s 属 %s，UTC %s 属 %s —— 这笔掉出了窗口\n",
				t.id, t.amt, t.occurred.In(cst).Format("01-02 15:04"), bucketOf(t.occurred, cst),
				t.occurred.UTC().Format("01-02 15:04"), bucketOf(t.occurred, nil))
		}
	}
	fmt.Println("  ★ 这种漂移最阴：若窗口里有偶数笔跨日界账、一进一出，行数对账可能侥幸通过，金额对账必炸；" +
		"所以行数与金额必须成对对，且口径时区要写进导出文件的元数据头（真环境验）。")

	sec(5, "本机验到什么程度 / 真环境要复跑哪几条（本程序一个字都没执行）")
	fmt.Println("  本机已验：四个口径各自独立算（记账循环 / 稠密桶函数 / CSV 文本逐行数 / summary 引用同一函数），" +
		"同值与差值都是返回值；UTC 日界漂移是当场造出来的，点名到具体笔号与金额差。\n" +
		"  本机没验：真 PG 的 date_trunc 按时区聚合是否与这里一致、导出服务分页取数会不会漏行——没 PG、没 Docker。\n" +
		"  真环境复跑：\n" +
		"    1) psql：SELECT date_trunc('month', occurred_at AT TIME ZONE 'Asia/Shanghai') 聚合，与本表并排比\n" +
		"    2) bash homecube/deploy/smoke/smoke.sh 后取导出 CSV：tail -n +2 | wc -l 与 psql count(*) 对\n" +
		"    3) curl home/summary 的账目摘要区，与报表接口同窗口的 month_total_cents 逐字比\n" +
		"    4) 拿一笔 UTC/CST 跨日界的账验证导出与报表归同一桶（本程序第 4 节的就是候选题）")
}

// W59 d17：README 的可复现标准（判据③：另一台干净机器照文档能跑通）
//
// README 最常见的死法不是写漏，是「写真的」——写的时候一切正常，改完 compose 忘了改文档：
// 端口从 8082 改成 8081 只改了半边、make 的 target 早就重命名、版本号抄了个 latest。
// 判据③要求另一台干净机器从零跑通，这些过期行会直接把陌生人卡在第一步。所以今天把 README
// 当产物来验：程序生成 README 四段（安装/启动/迁移/冒烟），再用一张「仓库真身登记表」逐条对账——
// 文档里出现的每条命令要么命中登记表里的真 target/真文件，要么是声明过的前置二进制；端口和版本号
// 必须与 compose 侧的注册表逐字一致。三个反例（编不出来的 target、半边端口、latest）当场检出名行号。
// 本机没有 Docker/nginx/PG：全程只是文本生成 + 静态对账，一条命令都没执行。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d17
package main

import (
