func known(s, path string) bool {
	for _, f := range repo.files {
		if s == f || strings.HasPrefix(path, f) {
			return true
		}
	}
	return false
}

// audit：逐行扫 README，命令→登记表、端口→注册表、版本→钉死清单，三本账都对上才算可复现
func audit(t string) (int, int) {
	bad, checked := 0, 0
	lines := strings.Split(t, "\n")
	for i, ln := range lines {
		c, ok := strings.CutPrefix(strings.TrimSpace(ln), "$ ")
		if !ok {
			continue
		}
		checked++
		f := strings.Fields(c)
		why := ""
		switch {
		case !contains(repo.binaries, f[0]):
			why = "二进制不在前置依赖清单"
		case f[0] == "make":
			target := ""
			if len(f) > 1 && !strings.HasPrefix(f[1], "#") {
				target = f[1]
			}
			if target == "" || !contains(repo.targets, target) {
				why = fmt.Sprintf("Makefile 没有 target「%s」", target)
			} else {
				why = "命中 target:" + target
			}
		case f[0] == "bash" || f[0] == "cp":
			hit := ""
			for _, a := range f {
				if strings.HasPrefix(a, "deploy/") {
					hit = a
				}
			}
			switch {
			case hit == "":
				why = "没有可登记的仓库路径"
			case known(hit, hit):
				why = "命中文件:" + hit
			default:
				why = "文件不在登记表:" + hit
			}
		case f[0] == "docker" && contains(f, "-f"):
			p := f[len(f)-1]
			if i2 := strings.Index(c, "deploy/compose.yaml"); i2 >= 0 {
				p = "deploy/compose.yaml"
			}
			if known(p, p) {
				why = "命中文件:" + p
			} else {
				why = "compose 文件不存在:" + p
			}
		default:
			why = "前置二进制 " + f[0] + "，参数不涉产物"
		}
		hit := strings.HasPrefix(why, "命中") || strings.HasPrefix(why, "前置二进制")
		bad += map[bool]int{true: 0, false: 1}[hit]
		fmt.Printf("  %s 第 %2d 行  %-58s %s\n", mk[hit], i+1, c, why)
	}
	// 端口账：README 端口行与 compose 注册表逐字比
	var pw []string
	for _, svc := range []string{"homeos", "finance", "calendar", "nginx", "postgres"} {
		want := fmt.Sprintf("%s %d", svc, repo.ports[svc])
		ok := strings.Contains(t, want)
		pw = append(pw, fmt.Sprintf("%s(%s)", svc, mk[ok]))
		bad += map[bool]int{true: 0, false: 1}[ok]
	}
	fmt.Printf("  端口五处对账：%s（值来自 compose 注册表，README 必须逐字出现「服务名 端口」）\n", strings.Join(pw, " "))
	// 版本账：钉死清单每一项必须在 README 出现；latest 出现即 ❌
	for _, v := range repo.vers {
		ok := strings.Contains(t, v)
		bad += map[bool]int{true: 0, false: 1}[ok]
		fmt.Printf("  %s 版本钉死 %-32s README 出现：%v\n", mk[ok], v, ok)
	}
	if n := strings.Count(t, ":latest"); n > 0 {
		for i, ln := range lines {
			if strings.Contains(ln, ":latest") {
				fmt.Printf("  ❌ 第 %d 行出现 :latest —— 同一文档在不同日期会装出不同环境，判据③当场作废\n", i+1)
			}
		}
		bad++
	}
	return checked, bad
}

func contains(v []string, x string) bool {
	for _, s := range v {
		if s == x {
			return true
		}
	}
	return false
}

