// W59 d18：演示与讲法（判据④）—— 对着整个系统讲一遍数据从哪来、到哪去、谁写谁读
//
// 毕业演示不是背架构图，而是被任意指着一条链路问「这笔钱谁写的、谁在读、两个服务怎么协作」都答得出。
// 靠嘴背必然背漏，所以今天把 S8-S12 的契约汇成一张「面 × 表 × 事件 × 读取方」总表——表里的每一格
// 都由本程序自己的对象与函数算出：谁写由表的 writer 字段给、谁读由 readers 列表给、事件流向由 from/to
// 边表给，一致性（family_id 全表覆盖、金额列全 _cents、动态流只由总线写、每个摘要区只有一处供数、
// 事件恰好一个发起方）全部现算现验。讲不圆的地方就是契约有洞的地方——这张表就是演示前的自查工具。
// 本机没有任何服务在跑：全部内容在内存对象上计算，真库核验留给「真环境复跑」。
// 学员侧跑法：cd homecube/server && go run ./lab/s14/d18
package main

import (
	"fmt"
	"sort"
	"strings"
)

var mk = map[bool]string{true: "✅", false: "❌"}

func sec(n int, t string) { fmt.Printf("\n===== %d. %s =====\n", n, t) }

type tbl struct {
	face    string // 面（服务）
	name    string
	writer  string   // 唯一写入口（API handler 或事件总线）
	readers []string // 读取方（端点级）
	fam     bool     // family_id 列在不在
	amts    []string // 金额列名（必须全部 *_cents）
}

type edge struct { // 事件边：谁发、谁收、幂等键
	name, from string
	to         []string
	dedup      string
}

var tables = []tbl{
	{"finance", "finance_account", "API POST /v1/accounts", []string{"/v1/accounts", "转账前置校验"}, true, nil},
	{"finance", "finance_transaction", "API POST /v1/transactions(crid)", []string{"报表月桶", "导出 CSV", "home/summary.账目摘要"}, true, []string{"amount_cents", "balance_cents"}},
	{"finance", "finance_budget_period", "API PUT /v1/budgets/{period}", []string{"报表预算带", "/v1/budgets"}, true, []string{"budget_cents", "spent_cents"}},
	{"finance", "finance_outbox", "API 同事务 INSERT（发布器只读）", []string{"事件发布器"}, true, nil},
	{"calendar", "calendar_due", "事件 due.registered 消费落库", []string{"到期中心", "home/summary.待办提醒"}, true, nil},
	{"calendar", "calendar_reminder", "API PUT /v1/reminders/{due_id}", []string{"到期中心"}, true, nil},
	{"homeos", "homeos_notification", "事件 due.soon 消费落库", []string{"home/summary.通知未读", "/v1/notifications"}, true, nil},
	{"homeos", "homeos_activity", "事件总线投递（due.soon/txn.recorded 消费）", []string{"home/summary.最近动态", "/v1/feed"}, true, nil},
}

var edges = []edge{
	{"finance.due.registered", "finance", []string{"calendar"}, "(source_system, source_id, kind)"},
	{"finance.due.revoked", "finance", []string{"calendar"}, "(source_system, source_id, kind)"},
	{"calendar.due.soon", "calendar", []string{"homeos"}, "(source_system, source_id, kind)"},
	{"finance.txn.recorded", "finance", []string{"homeos"}, "(source_system, source_id, kind)"},
}

// summaryZones：S12 d21 的 home/summary 四区——每区的供数表必须只有一张（服务端聚合一处）。
var summaryZones = map[string]string{
	"账目摘要": "finance_transaction", "待办提醒": "calendar_due", "通知未读": "homeos_notification", "最近动态": "homeos_activity",
}

// zoneProviders 从 readers 反向算：某摘要区被哪些表供数（多于一张 = 双源漂移，当场点名）。
func zoneProviders(zone string) []string {
	var hits []string
	for _, t := range tables {
		for _, r := range t.readers {
			if strings.HasPrefix(r, "home/summary."+zone) {
				hits = append(hits, t.name)
			}
		}
	}
	return hits
}

func main() {
	sec(1, "总表：面 × 表 × 写入口 × 读取方（每一格都由对象字段算出，不是手抄）")
	faces := map[string]int{}
	for _, t := range tables {
		faces[t.face]++
	}
	var fn []string
	for f := range faces {
		fn = append(fn, f)
	}
	sort.Strings(fn)
	fmt.Printf("  规模：面 %d、表 %d、事件边 %d\n", len(fn), len(tables), len(edges))
	fmt.Println("  面         表                        写入口                              读取方")
	for _, t := range tables {
		fmt.Printf("  %-10s %-25s %-35s %s\n", t.face, t.name, t.writer, strings.Join(t.readers, " | "))
	}

	sec(2, "契约一致性（全部现算，任何一条不过就点名）")
