	fmt.Printf("  %s 金额列共 %d 个，非 _cents 后缀 %d 个 %v\n", mk[len(badAmt) == 0], amtN, len(badAmt), badAmt)
	feed := tables[len(tables)-1]
	fmt.Printf("  %s 动态流只由事件总线写：homeos_activity 写入口=「%s」，含「API」旁路写入入口：%v\n",
		mk[!strings.Contains(feed.writer, "API")], feed.writer, strings.Contains(feed.writer, "API"))
	var zoneBad int
	var zn []string
	for z := range summaryZones {
		zn = append(zn, z)
	}
	sort.Strings(zn)
	for _, z := range zn {
		hits := zoneProviders(z)
		ok := len(hits) == 1 && hits[0] == summaryZones[z]
		if !ok {
			zoneBad++
		}
		fmt.Printf("    %-6s 供数表=%v 契约声明=%s %s\n", z, hits, summaryZones[z], mk[ok])
	}
	fmt.Printf("  %s 聚合与未数一处：四区供数唯一（多出任何一张就是双源漂移）\n", mk[zoneBad == 0])
	wrong, evNoWriter := 0, 0
	for _, e := range edges {
		froms := map[string]bool{e.from: true}
		for _, x := range edges {
			if x.name == e.name {
				froms[x.from] = true
			}
		}
		if len(froms) != 1 || len(e.to) == 0 {
			wrong++
		}
	}
	for _, e := range edges {
		n := 0
		for _, t := range tables {
