	fmt.Printf("  %s 事件边 %d 条：每条恰好一个发起方、至少一个消费方，违反 %d 条；无落表消费方的边 %d 条\n",
		mk[wrong == 0 && evNoWriter == 0], len(edges), wrong, evNoWriter)
	xw := 0 // 跨面直写：A 面的表由 B 面的 API 写？协作只走事件
	for _, t := range tables {
		if strings.Contains(t.writer, "API") && strings.HasPrefix(t.writer, "API") {
			for _, f := range fn {
				if f != t.face && strings.Contains(t.writer, f) {
