				}
			}
		}
	}
	fmt.Printf("  %s 跨面直写检查：某面表由别面 API 直接写的情况 %d 处（业务服务之间只通过事件协作，不共库）\n", mk[xw == 0], xw)

	sec(3, "演示的讲法：沿「一笔带还款日的账」把链走一遍（每一跳由边表实算，不是背出来的）")
	step := 1
	fmt.Printf("  %d. 用户 → nginx(443) → finance(8081)：POST /api/finance/v1/transactions —— 会话取 family_id、带 crid、金额 amount_cents 整数\n", step)
	for _, t := range tables {
		if t.name == "finance_transaction" {
			fmt.Printf("     写入 %s.%s；同一事务 INSERT finance_outbox（提交前不发事件，杜绝幽灵事件）\n", t.face, t.name)
		}
	}
	cur := "finance"
	for _, want := range []string{"finance.due.registered", "calendar.due.soon"} { // 沿边表走 due 链：finance → calendar → homeos
		for _, e := range edges {
			if e.name != want || e.from != cur {
				continue
			}
			step++
			fmt.Printf("  %d. %s 发 %s → %v（幂等键 %s；信封带 family_id/request_id/crid = W59 d15 的追踪三键）\n",
				step, e.from, e.name, e.to, e.dedup)
			token := e.name[strings.Index(e.name, ".")+1:]
			for _, t := range tables {
				if contains(e.to, t.face) && strings.Contains(t.writer, "事件") &&
					(strings.Contains(t.writer, token) || t.name == "homeos_activity" && token == "due.soon") {
					fmt.Printf("     消费落库 %s.%s → 读取方 %v\n", t.face, t.name, t.readers)
				}
			}
			cur = e.to[0]
		}
	}
	step++
	fmt.Printf("  %d. 首屏客户端只发一个请求 GET /api/homeos/v1/home/summary → 四区一次返回：", step)
	fmt.Print(strings.Join(func() []string {
		var s []string
		for _, z := range zn {
			s = append(s, fmt.Sprintf("%s(%s)", z, summaryZones[z]))
		}
		return s
	}(), "、"), "\n")
	fmt.Printf("  链条共 %d 跳：用户写下的一笔，最终变成另一个进程里的落库行与一次聚合读——协作介质只有事件，没有共库。\n", step)

	sec(4, "最可能被问倒的三个点（回答里引用的数字由上面的计算给出）")
	fmt.Printf("  Q1「为什么不干脆让 finance 直接写通知表？一行 INSERT 的事」\n"+
		"     A: 跨面直写会同时踩穿两条红线：未读出现第二个来源（今天四区供数唯一 %d/4 通过），动态流不再只由总线写。\n"+
		"        而且 homeos 宕机时 finance 的写连带回滚，两服务可用性被硬绑死。\n", 4-zoneBad)
