type card struct {
	id, title string
	strs      []string // 卡片里全部字符串字段（证据检索面）
}

var corpus, selfTest []card

func collect(v any, out *[]string) { // 递归收集卡片里每一条字符串——证据必须能落到原文
	switch x := v.(type) {
	case string:
		*out = append(*out, x)
	case map[string]any:
		var ks []string
		for k := range x {
			ks = append(ks, k)
		}
		sort.Strings(ks)
		for _, k := range ks {
			collect(x[k], out)
		}
	case []any:
		for _, e := range x {
			collect(e, out)
		}
	}
}

func load(dir string) int {
	files, _ := filepath.Glob(filepath.Join(dir, "S*.json"))
	sort.Strings(files)
	n := 0
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			continue
		}
		var cs []map[string]any
		if err := json.Unmarshal(b, &cs); err != nil {
			fmt.Printf("  （%s 不是卡片数组，跳过）\n", filepath.Base(f))
			continue
		}
		for _, c := range cs {
			cd := card{}
			cd.id, _ = c["id"].(string)
			cd.title, _ = c["title"].(string)
			collect(c, &cd.strs)
			corpus = append(corpus, cd)
			if strings.Contains(cd.title, "判据") || strings.Contains(cd.title, "自测") {
				selfTest = append(selfTest, cd)
			}
			n++
		}
	}
	return n
}

func key(s string) int { // 出处排序键：stage*1000+day，s11-d33 → 11033
	var st, d int
	_, _ = fmt.Sscanf(s, "s%d-d%d", &st, &d)
	return st*1000 + d
}

func grep(cs []card, tok string) (hits int, firstID, firstQuote string) {
	var ids []string
	for _, c := range cs {
		h := 0
		for _, s := range c.strs {
			if n := strings.Count(s, tok); n > 0 {
				h += n
				if firstQuote == "" { // 字节安全取窗：先按字节切，再按 rune 收边；换行折成 ⏎ 保持单行展示
					i := strings.Index(s, tok)
					pre, post := s[:i], s[i+len(tok):]
					q := tailRunes(pre, 12) + "「" + tok + "」" + headRunes(post, 28)
					firstQuote = strings.ReplaceAll(strings.ReplaceAll(q, "\r", ""), "\n", " ⏎ ")
				}
			}
		}
		if h > 0 {
			hits += h
			ids = append(ids, c.id)
		}
	}
	if len(ids) > 0 {
		sort.Slice(ids, func(a, b int) bool { return key(ids[a]) < key(ids[b]) })
		firstID = ids[0]
	}
	return
}

func headRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n]) + "…"
	}
	return s
}

func tailRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return "…" + string(r[len(r)-n:])
	}
	return s
}

func cut(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n]) + "…"
}

